-- 0058: تعليمات العمل (scope=wi) — المستوى التنفيذي تحت الإجراءات: تنظيف الفينيل ودورات المياه والجانيتور، صيانة المكيفات بأنواعها، المولد، الخزانات، الطفايات، إنارة الطوارئ
-- لكل تعليمات قائمة تحقق (checklist) تُستورد في خطط الصيانة الدورية؛ وops_plans.wi يربط الخطة بتعليماتها فيظهر رابطها للفني في أمر العمل. القاعدة R-45. البذرة لا تستبدل التعديلات.
alter table public.manual_templates add column if not exists checklist jsonb not null default '[]'::jsonb;
alter table public.manual_templates add column if not exists unit text not null default '';
alter table public.manual_templates add column if not exists cat text not null default '';
alter table public.manual_templates add column if not exists card jsonb not null default '{}'::jsonb;
alter table public.ops_plans add column if not exists wi text not null default '';
-- صور الميدان على التعليمات والأدلة: المرفقات بالمفتاح wi:CODE — يقرؤها كل مستخدم نشط، ويرفعها المسؤول والمهندسون وموظفو أقسام التشغيل
drop policy if exists p_wi_read on public.attachments;
create policy p_wi_read on public.attachments for select using (ref like 'wi:%' and public.is_active_user());
drop policy if exists p_wi_ins on public.attachments;
create policy p_wi_ins on public.attachments for insert with check (ref like 'wi:%' and by_user = auth.uid() and (public.is_admin() or public.can_edit() or public.my_unit() in ('GEN','MNT','SAF','FAC','BME','IT')));
drop policy if exists p_wi_del on public.attachments;
create policy p_wi_del on public.attachments for delete using (ref like 'wi:%' and (public.is_admin() or by_user = auth.uid()));
do $$ begin
  drop policy if exists pf_wi_read on storage.objects;
  create policy pf_wi_read on storage.objects for select to authenticated using (bucket_id = 'project-files' and name like 'attach/wi\_%' and public.is_active_user());
  drop policy if exists pf_wi_ins on storage.objects;
  create policy pf_wi_ins on storage.objects for insert to authenticated with check (bucket_id = 'project-files' and name like 'attach/wi\_%' and (public.is_admin() or public.can_edit() or public.my_unit() in ('GEN','MNT','SAF','FAC','BME','IT')));
  drop policy if exists pf_wi_del on storage.objects;
  create policy pf_wi_del on storage.objects for delete to authenticated using (bucket_id = 'project-files' and name like 'attach/wi\_%' and (public.is_admin() or owner = auth.uid()));
exception when insufficient_privilege or undefined_table then raise notice 'storage policies skipped'; end $$;

insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C01','تنظيف أرضيات الفينيل والعناية بها','عمالة النظافة ومشرفوها، ومراقب عقد النظافة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "أرضيات الفينيل الملحوم في المناطق السريرية جزء من مكافحة العدوى: سطح واحد بلا فواصل يُنظف ويُطهر بسهولة. التنظيف الخاطئ (ماء كثير، مواد قوية، شمع) يتلف الطبقة الواقية ويفتح اللحامات ويقصّر عمر الأرضية.\n- تنطبق على كل أرضيات الفينيل (المتجانس وغير المتجانس) في منشآت التجمع.\n- تُتبع تعليمات الصانع إن خالفت هذا الدليل، وتُحفظ في دليل المنشأة (قسم الخامات).\n> أغلب الفينيل الحديث مغطى بطبقة واقية (PUR) لا تحتاج شمعاً ولا تجريداً؛ التجريد يزيلها نهائياً."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات مطاطية مناسبة للمادة الكيميائية، ونظارة عند الرش أو الخلط\n- حذاء مانع للانزلاق\n- لافتة «أرضية مبللة» قبل البدء وحتى الجفاف التام\n- قراءة بطاقة بيانات السلامة لكل مادة وعدم خلط المواد إطلاقاً (H-04)"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- ممسحة جافة من الألياف الدقيقة (مايكروفايبر) لإزالة الغبار\n- ممسحة رطبة بنظام الدلوين (ماء نظيف وماء متسخ) أو ممسحة مشبعة مسبقاً\n- منظف متعادل (درجة حموضة بين 6 و8 تقريباً) مخفف بحسب تعليمات الصانع\n- مطهر معتمد من مكافحة العدوى ومتوافق مع الفينيل\n- آلة غسيل وتجفيف (Scrubber) بلباد ناعم (أحمر أو أبيض) للمساحات الكبيرة\n- لافتات الأرضية المبللة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | إزالة الغبار والأوساخ الجافة بالممسحة الجافة، من الأطراف إلى الوسط | لا رمل أو حصى؛ الرمل يخدش الطبقة الواقية |\n| 2 | تحضير المنظف المتعادل بالتخفيف المحدد على العبوة، بماء فاتر | لا زيادة في التركيز؛ التركيز العالي يترك طبقة لزجة |\n| 3 | المسح الرطب بممسحة معصورة جيداً بحركة 8 أو بخطوط متداخلة | لا ماء متجمع، خاصة عند اللحامات والحواف |\n| 4 | تغيير الماء والممسحة عند اتساخها، وبين كل غرفة وأخرى في المناطق السريرية | لا نقل للأوساخ بين الغرف |\n| 5 | في المناطق السريرية: التطهير بالمطهر المعتمد ومدة التلامس المحددة | المدة على العبوة تُحترم قبل التجفيف |\n| 6 | إزالة البقع فوراً بقطعة مايكروفايبر والمنظف المتعادل، أو المزيل الذي يحدده الصانع | لا شفرات ولا ليف معدني ولا مذيبات |\n| 7 | التجفيف أو ترك الأرضية تجف مع بقاء اللافتة | رفع اللافتة بعد الجفاف التام فقط |\n| 8 | أسبوعياً للمساحات الكبيرة: الغسيل بالآلة باللباد الناعم والمنظف المتعادل مع الشفط في نفس المرور | لا لباد أسود أو بني (للتجريد) |\n| 9 | دورياً: التلميع الجاف بالآلة عالية السرعة إذا أوصى به الصانع لاستعادة اللمعة | بدون شمع على الفينيل المغطى بطبقة PUR |\n| 10 | تسجيل التنظيف في سجل المنطقة أو قائمة التحقق في المنصة | السجل محدث ومؤرخ |"}, {"key": "damage", "title": "الإبلاغ عن التلف", "body": "أي لحام مفتوح أو طرف مرفوع أو انتفاخ أو ثقب يُبلَّغ عنه فوراً برمز الغرفة (R-16)؛ الفتحة في الفينيل تسمح بتسرب الماء تحته وتجمع البكتيريا.\n- في فترة الضمان يُطالب به المقاول عبر قسم المشاريع (P-14).\n- الإصلاح باللحام الحراري بالخامة نفسها ورمزها، لا بالسيليكون أو اللاصق."}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| إزالة الغبار والمسح الرطب — المناطق السريرية والممرات | يومياً على الأقل، وعند الحاجة |\n| التطهير — غرف الكشف والإجراءات والعزل | بعد كل حالة تلوث ويومياً |\n| الغسيل بالآلة — الممرات والانتظار | أسبوعياً |\n| التلميع الجاف (إن أوصى الصانع) | شهرياً أو ربع سنوياً |\n| فحص اللحامات والحواف والانتفاخ | شهرياً ضمن الجولة |"}, {"key": "accept", "title": "معايير القبول", "body": "- سطح نظيف بلا بقع أو آثار أقدام أو طبقة لزجة\n- لا ماء متجمع عند اللحامات أو الحواف المقلوبة\n- لمعة متجانسة بلا خطوط\n- لا خدوش جديدة أو أطراف مرفوعة"}, {"key": "donts", "title": "ممنوعات", "body": "- الشمع أو مواد التلميع على الفينيل المغطى بطبقة PUR\n- التجريد باللباد الأسود أو المواد القلوية القوية\n- المذيبات (أسيتون، ثنر) والمبيضات المركزة دون شطف\n- الماء الكثير أو الغسيل بالخرطوم\n- جر الأثاث والأجهزة على الأرضية؛ تُستخدم واقيات للأرجل\n- الأقدام المطاطية السوداء على الأثاث (تترك بقعاً دائمة)"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01 · R-32 · H-04", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',1,'recycle','التنظيف والنظافة','GEN','["إزالة الغبار بالممسحة الجافة", "المسح الرطب بالمنظف المتعادل بالتخفيف الصحيح", "التطهير بمدة التلامس في المناطق السريرية", "لا ماء متجمع عند اللحامات والحواف", "إزالة البقع دون مواد كاشطة", "فحص اللحامات والأطراف والإبلاغ عن أي تلف", "السجل محدث"]'::jsonb,'{"ppe": ["gloves", "boots", "wetsign"], "steps": [{"i": "wetsign", "t": {"ar": "ضع لافتة الأرضية المبللة", "en": "Place the wet floor sign", "ur": "گیلے فرش کا بورڈ لگائیں", "bn": "ভেজা মেঝের সাইন রাখুন", "hi": "गीले फर्श का बोर्ड लगाएं", "tl": "Ilagay ang karatulang basa ang sahig"}}, {"i": "broom", "t": {"ar": "أزل الغبار بالممسحة الجافة", "en": "Remove dust with a dry mop", "ur": "خشک پوچے سے دھول ہٹائیں", "bn": "শুকনো মপ দিয়ে ধুলো সরান", "hi": "सूखे पोछे से धूल हटाएं", "tl": "Alisin ang alikabok gamit ang tuyong mop"}}, {"i": "dilute", "t": {"ar": "خفف المنظف المتعادل حسب التعليمات", "en": "Dilute neutral cleaner as instructed", "ur": "نیوٹرل کلینر ہدایت کے مطابق ملائیں", "bn": "নির্দেশ অনুযায়ী নিউট্রাল ক্লিনার মেশান", "hi": "न्यूट्रल क्लीनर निर्देश अनुसार घोलें", "tl": "Tunawin ang neutral cleaner ayon sa tagubilin"}}, {"i": "mop", "t": {"ar": "امسح بممسحة معصورة جيداً", "en": "Mop with a well-wrung mop", "ur": "اچھی طرح نچوڑے پوچے سے صاف کریں", "bn": "ভালোভাবে নিংড়ানো মপ দিয়ে মুছুন", "hi": "अच्छी तरह निचोड़े पोछे से पोंछें", "tl": "Mag-mop gamit ang pigang-pigang mop"}}, {"i": "drop", "t": {"ar": "لا تترك ماء على اللحامات والحواف", "en": "No standing water on seams and edges", "ur": "جوڑوں اور کناروں پر پانی نہ چھوڑیں", "bn": "জোড়া ও কিনারায় পানি জমতে দেবেন না", "hi": "जोड़ों और किनारों पर पानी न छोड़ें", "tl": "Walang tubig sa mga dugtungan at gilid"}}, {"i": "bucket", "t": {"ar": "غيّر الماء والممسحة بين الغرف", "en": "Change water and mop between rooms", "ur": "کمروں کے درمیان پانی اور پوچا بدلیں", "bn": "রুমের মাঝে পানি ও মপ বদলান", "hi": "कमरों के बीच पानी और पोछा बदलें", "tl": "Palitan ang tubig at mop sa bawat kuwarto"}}, {"i": "spray", "t": {"ar": "في المناطق الطبية: طهّر واترك المطهر المدة المحددة", "en": "Clinical areas: disinfect and wait the contact time", "ur": "طبی جگہوں میں: جراثیم کش لگائیں اور مقررہ وقت انتظار کریں", "bn": "চিকিৎসা এলাকায়: জীবাণুনাশক দিন ও নির্দিষ্ট সময় অপেক্ষা করুন", "hi": "चिकित्सा क्षेत्र में: कीटाणुनाशक लगाएं और तय समय रुकें", "tl": "Sa klinikal na lugar: mag-disinfect at hintayin ang oras"}}, {"i": "clock", "t": {"ar": "ارفع اللافتة بعد الجفاف التام فقط", "en": "Remove the sign only when fully dry", "ur": "مکمل خشک ہونے کے بعد ہی بورڈ ہٹائیں", "bn": "পুরো শুকানোর পরই সাইন সরান", "hi": "पूरी तरह सूखने के बाद ही बोर्ड हटाएं", "tl": "Alisin ang karatula kapag tuyo na"}}, {"i": "clipboard", "t": {"ar": "سجّل التنظيف", "en": "Record the cleaning", "ur": "صفائی کا اندراج کریں", "bn": "পরিষ্কারের রেকর্ড লিখুন", "hi": "सफाई दर्ज करें", "tl": "Itala ang paglilinis"}}], "donts": [{"i": "nowax", "t": {"ar": "لا شمع ولا تجريد", "en": "No wax, no stripping", "ur": "موم اور اسٹرپنگ منع ہے", "bn": "মোম ও স্ট্রিপিং নিষেধ", "hi": "मोम और स्ट्रिपिंग मना है", "tl": "Bawal ang wax at stripping"}}, {"i": "nohose", "t": {"ar": "لا ماء كثير ولا خرطوم", "en": "No flooding, no hose", "ur": "زیادہ پانی یا پائپ منع ہے", "bn": "বেশি পানি বা পাইপ নিষেধ", "hi": "ज़्यादा पानी या पाइप मना है", "tl": "Bawal ang maraming tubig at hose"}}, {"i": "noscrape", "t": {"ar": "لا ليف معدني ولا شفرات", "en": "No steel wool, no blades", "ur": "اسٹیل وول یا بلیڈ منع ہے", "bn": "স্টিল উল বা ব্লেড নিষেধ", "hi": "स्टील वूल या ब्लेड मना है", "tl": "Bawal ang steel wool at blade"}}, {"i": "nodrag", "t": {"ar": "لا تجر الأثاث على الأرضية", "en": "Do not drag furniture", "ur": "فرنیچر نہ گھسیٹیں", "bn": "আসবাব টেনে নেবেন না", "hi": "फर्नीचर न घसीटें", "tl": "Huwag hilahin ang muwebles"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C02','تنظيف دورات المياه وتطهيرها','عمالة النظافة ومشرفوها','[{"key": "purpose", "title": "الغرض والنطاق", "body": "دورات المياه أكثر مكان يلاحظه المراجع، وأكثر مكان تنتقل فيه العدوى إذا نُظف بطريقة خاطئة. القاعدة: من الأعلى إلى الأسفل، ومن الأنظف إلى الأكثر اتساخاً، والمرحاض آخراً.\n- تنطبق على دورات المياه العامة ودورات مياه الغرف ودورات المياه المهيأة لذوي الإعاقة.\n- نظام الألوان للأدوات (WI-C09): الأحمر لدورات المياه، والأزرق للمناطق العامة، والأصفر لمناطق العزل والمناطق السريرية، والأخضر لمناطق الطعام."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات مطاطية مناسبة للمادة الكيميائية، ونظارة عند الرش أو الخلط\n- حذاء مانع للانزلاق\n- لافتة «أرضية مبللة» قبل البدء وحتى الجفاف التام\n- قراءة بطاقة بيانات السلامة لكل مادة وعدم خلط المواد إطلاقاً (H-04)\n- قفازات خاصة بدورات المياه (حمراء) لا تُستخدم في أي مكان آخر"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- أدوات حمراء فقط: قطع مايكروفايبر، فرشاة المرحاض، ممسحة ودلو\n- منظف حمضي خفيف للأحواض والمراحيض (لإزالة الترسبات) بحسب المعتمد\n- منظف متعادل للأسطح والأرضيات\n- مطهر معتمد من مكافحة العدوى\n- مستهلكات: صابون، مناديل، ورق، أكياس نفايات\n- لافتة «جاري التنظيف» وسجل التنظيف على الباب"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | وضع لافتة «جاري التنظيف» والتأكد من خلو المكان | المدخل مؤمَّن |\n| 2 | التهوية: التأكد من عمل مروحة الشفط | المروحة تعمل؛ وإلا بلاغ صيانة |\n| 3 | تفريغ سلال النفايات واستبدال الأكياس، والحاويات الصحية النسائية | كيس جديد بالحجم الصحيح |\n| 4 | تنظيف المرايا والأسطح العالية والرفوف وموزعات الصابون والمناديل | بلا بقع ماء أو بصمات |\n| 5 | تنظيف وتطهير نقاط اللمس: مقابض الأبواب، الأقفال، مفاتيح الإنارة، الصنابير، أزرار السيفون، مقابض الدعم | كل نقطة لمس بقطعة نظيفة |\n| 6 | تنظيف الأحواض والصنابير من الداخل والخارج وإزالة الترسبات | لا ترسبات أو شعر في التصريف |\n| 7 | المرحاض آخراً: السيفون أولاً ثم المنظف داخل الحوض، الخارج والقاعدة والمقعد من الأعلى للأسفل، ثم الفرك بالفرشاة والسيفون | مدة تلامس المطهر محترمة |\n| 8 | المباول: التنظيف والتطهير وتغيير قطع التعطير إن وُجدت | بلا روائح |\n| 9 | إعادة تعبئة المستهلكات كاملة | لا موزع فارغ |\n| 10 | مسح الأرضية آخراً من الداخل باتجاه الباب، مع الأركان وخلف المرحاض والتصريف الأرضي | لا ماء متجمع |\n| 11 | فحص الأعطال: تسرب، سيفون، صنبور، إنارة، قفل، مروحة | كل عطل بلاغ برمز الغرفة |\n| 12 | تسجيل الوقت والاسم في سجل الباب أو المنصة | السجل محدث |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| التنظيف الروتيني — دورات المياه العامة عالية الاستخدام | كل ساعتين على الأقل، وعند الحاجة |\n| التنظيف الروتيني — دورات مياه الغرف | يومياً، وعند خروج المريض |\n| التنظيف العميق: الجدران والبلاط والفواصل والتصريف الأرضي | أسبوعياً |\n| إزالة الترسبات الكلسية | أسبوعياً أو حسب الحاجة |\n| فحص الجودة من المشرف | يومياً بعينة |"}, {"key": "accept", "title": "معايير القبول", "body": "- بلا روائح، بلا بقع أو ترسبات، بلا ماء على الأرض\n- المستهلكات ممتلئة\n- السجل موقّع في الوقت المحدد\n- لا أعطال غير مبلغ عنها"}, {"key": "donts", "title": "ممنوعات", "body": "- استخدام أدوات دورات المياه (الحمراء) في أي مكان آخر\n- خلط المنظف الحمضي مع الكلور أو أي مادة أخرى (غازات سامة)\n- ترك الأدوات أو المواد في دورة المياه\n- تنظيف المرحاض قبل الحوض والأسطح\n- رش المواد على المقابس والمفاتيح الكهربائية مباشرة"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01 · S-02 · R-31 · R-32", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',2,'recycle','التنظيف والنظافة','GEN','["تفريغ النفايات واستبدال الأكياس", "المرايا والأسطح العالية", "تطهير نقاط اللمس", "الأحواض والصنابير", "المرحاض والمباول آخراً", "إعادة تعبئة المستهلكات", "الأرضية والتصريف", "فحص الأعطال والإبلاغ", "توقيع السجل"]'::jsonb,'{"ppe": ["gloves_red", "goggles", "boots"], "steps": [{"i": "sign", "t": {"ar": "ضع لافتة «جاري التنظيف»", "en": "Place the \"Cleaning in progress\" sign", "ur": "\"صفائی جاری ہے\" کا بورڈ لگائیں", "bn": "\"পরিষ্কার চলছে\" সাইন রাখুন", "hi": "\"सफाई चल रही है\" बोर्ड लगाएं", "tl": "Ilagay ang karatulang \"Naglilinis\""}}, {"i": "fan", "t": {"ar": "تأكد أن مروحة الشفط تعمل", "en": "Check the exhaust fan works", "ur": "ایگزاسٹ فین چیک کریں", "bn": "এক্সহস্ট ফ্যান চালু আছে কিনা দেখুন", "hi": "एग्जॉस्ट फैन चेक करें", "tl": "Tingnan kung gumagana ang exhaust fan"}}, {"i": "bin", "t": {"ar": "فرّغ السلال وغيّر الأكياس", "en": "Empty bins and change bags", "ur": "کوڑے دان خالی کریں اور تھیلے بدلیں", "bn": "ঝুড়ি খালি করে ব্যাগ বদলান", "hi": "कूड़ेदान खाली करें और थैले बदलें", "tl": "Alisan ng laman ang basurahan at palitan ang supot"}}, {"i": "mirror", "t": {"ar": "نظّف المرايا والأسطح العالية", "en": "Clean mirrors and high surfaces", "ur": "آئینے اور اوپر کی سطحیں صاف کریں", "bn": "আয়না ও উঁচু জায়গা পরিষ্কার করুন", "hi": "शीशे और ऊंची सतहें साफ करें", "tl": "Linisin ang salamin at matataas na bahagi"}}, {"i": "hand", "t": {"ar": "طهّر المقابض والصنابير والأزرار", "en": "Disinfect handles, taps and buttons", "ur": "ہینڈل، نل اور بٹن جراثیم سے پاک کریں", "bn": "হ্যান্ডেল, কল ও বোতাম জীবাণুমুক্ত করুন", "hi": "हैंडल, नल और बटन कीटाणुरहित करें", "tl": "I-disinfect ang hawakan, gripo at buton"}}, {"i": "sink", "t": {"ar": "نظّف الأحواض والصنابير", "en": "Clean sinks and taps", "ur": "سنک اور نل صاف کریں", "bn": "বেসিন ও কল পরিষ্কার করুন", "hi": "सिंक और नल साफ करें", "tl": "Linisin ang lababo at gripo"}}, {"i": "toilet", "t": {"ar": "المرحاض آخراً: من الأعلى إلى الأسفل", "en": "Toilet last: top to bottom", "ur": "ٹوائلٹ آخر میں: اوپر سے نیچے", "bn": "টয়লেট শেষে: ওপর থেকে নিচে", "hi": "शौचालय आखिर में: ऊपर से नीचे", "tl": "Inidoro ang huli: mula taas pababa"}}, {"i": "refill", "t": {"ar": "املأ الصابون والمناديل والورق", "en": "Refill soap, towels and paper", "ur": "صابن، تولیے اور کاغذ بھریں", "bn": "সাবান, টিস্যু ও কাগজ ভরুন", "hi": "साबुन, तौलिया और कागज भरें", "tl": "Punuin ang sabon, tuwalya at papel"}}, {"i": "mop", "t": {"ar": "امسح الأرضية آخراً باتجاه الباب", "en": "Mop the floor last, toward the door", "ur": "آخر میں فرش دروازے کی طرف صاف کریں", "bn": "শেষে দরজার দিকে মেঝে মুছুন", "hi": "आखिर में फर्श दरवाजे की ओर पोंछें", "tl": "Huling i-mop ang sahig papunta sa pinto"}}, {"i": "wrench", "t": {"ar": "أبلغ عن أي عطل", "en": "Report any fault", "ur": "کوئی خرابی ہو تو بتائیں", "bn": "যেকোনো সমস্যা জানান", "hi": "कोई खराबी हो तो बताएं", "tl": "I-report ang anumang sira"}}, {"i": "clipboard", "t": {"ar": "وقّع سجل الباب", "en": "Sign the door log", "ur": "دروازے کے رجسٹر پر دستخط کریں", "bn": "দরজার খাতায় সই করুন", "hi": "दरवाजे के रजिस्टर पर हस्ताक्षर करें", "tl": "Pumirma sa talaan sa pinto"}}], "donts": [{"i": "red", "t": {"ar": "الأدوات الحمراء لدورات المياه فقط", "en": "Red tools for toilets only", "ur": "سرخ اوزار صرف ٹوائلٹ کے لیے", "bn": "লাল সরঞ্জাম শুধু টয়লেটের জন্য", "hi": "लाल औजार सिर्फ शौचालय के लिए", "tl": "Pulang gamit para sa CR lamang"}}, {"i": "nomix", "t": {"ar": "لا تخلط المواد الكيميائية أبداً", "en": "Never mix chemicals", "ur": "کیمیکل کبھی نہ ملائیں", "bn": "কখনো রাসায়নিক মেশাবেন না", "hi": "रसायन कभी न मिलाएं", "tl": "Huwag kailanman paghaluin ang kemikal"}}, {"i": "nospray", "t": {"ar": "لا ترش على المقابس الكهربائية", "en": "Do not spray on electric sockets", "ur": "بجلی کے ساکٹ پر اسپرے نہ کریں", "bn": "বৈদ্যুতিক সকেটে স্প্রে করবেন না", "hi": "बिजली के सॉकेट पर स्प्रे न करें", "tl": "Huwag mag-spray sa saksakan"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C03','غرفة عامل النظافة (الجانيتور): التنظيم والاستخدام','عمالة النظافة ومشرفوها، والأمن والسلامة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "غرفة الجانيتور هي مصدر النظافة في الطابق أو مصدر العدوى فيه. الأدوات التي تُغسل وتُخزن فيها بطريقة خاطئة تنقل الجراثيم لكل غرفة تدخلها.\n- تنطبق على كل غرف عمال النظافة ومخازن مواد التنظيف في المنشآت."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات ونظارة عند خلط المواد أو تعبئتها\n- بطاقات بيانات السلامة معلقة ومتاحة لكل مادة (H-04، R-20)\n- غسول عيون قريب حيث تُخلط المواد المركزة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- حوض أرضي (مغسلة جانيتور) بماء حار وبارد\n- محطة تخفيف آلية للمواد أو أكواب قياس مميزة\n- رفوف معدنية أو بلاستيكية مرفوعة عن الأرض\n- حاملات معلقة للممسحات والمكانس\n- عربة التنظيف المرمزة بالألوان\n- سجل الغرفة وقائمة المواد المعتمدة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | الغرفة مقفلة دائماً، والمفتاح مع مشرف النظافة | لا دخول لغير المختصين |\n| 2 | المواد على الرفوف بحسب التوافق: الأحماض بعيداً عن الكلور والقلويات، والقابلة للاشتعال بعيداً عن الحرارة | لا مواد على الأرض |\n| 3 | كل عبوة بملصقها الأصلي؛ العبوات المعاد تعبئتها عليها اسم المادة والتخفيف والتاريخ | لا عبوة بلا ملصق |\n| 4 | التخفيف من المحطة الآلية أو بأكواب القياس فقط | التركيز مطابق للتعليمات |\n| 5 | بعد كل استخدام: غسل الممسحات وقطع المايكروفايبر (أو إرسالها للمغسلة) وتجفيفها معلقة | لا ممسحة رطبة مخزنة في الدلو |\n| 6 | تفريغ الدلاء وغسلها وتجفيفها مقلوبة | لا ماء راكد |\n| 7 | تخزين الأدوات بحسب ألوانها منفصلة | الأحمر لا يلمس غيره |\n| 8 | تنظيف عربة التنظيف يومياً وإعادة ترتيبها | العربة نظيفة ومرتبة |\n| 9 | تنظيف الغرفة نفسها وحوضها ونهايتها يومياً | لا روائح أو رطوبة |\n| 10 | جرد المواد أسبوعياً وطلب الناقص | لا نقص ولا تخزين زائد |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| غسل الأدوات وتجفيفها | بعد كل وردية |\n| تنظيف الغرفة والعربة | يومياً |\n| جرد المواد وتحديث بطاقات السلامة | أسبوعياً، ومراجعة شاملة نصف سنوية (K-14) |\n| تفتيش المشرف | أسبوعياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- غرفة نظيفة جافة مهواة ومقفلة\n- المواد مرتبة بحسب التوافق وعليها ملصقاتها\n- الأدوات جافة ومفصولة بالألوان\n- بطاقات السلامة متاحة"}, {"key": "donts", "title": "ممنوعات", "body": "- الأكل أو الشرب أو تخزين الأغراض الشخصية في الغرفة\n- خلط المواد أو صب بقاياها في الحوض بعشوائية\n- تخزين الأدوات رطبة أو داخل الدلاء\n- استخدام الغرفة مخزناً لأي شيء آخر\n- ترك الباب مفتوحاً دون مراقبة"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01 · H-04 · R-20", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',3,'recycle','التنظيف والنظافة','GEN','["الغرفة مقفلة ومرتبة", "المواد بحسب التوافق وعليها ملصقات", "بطاقات السلامة معلقة", "الأدوات مغسولة ومجففة ومعلقة", "الدلاء فارغة جافة", "العربة نظيفة", "جرد المواد"]'::jsonb,'{"ppe": ["gloves", "goggles"], "steps": [{"i": "lock", "t": {"ar": "الغرفة مقفلة دائماً", "en": "Keep the room locked", "ur": "کمرہ ہمیشہ بند رکھیں", "bn": "রুম সবসময় তালাবদ্ধ রাখুন", "hi": "कमरा हमेशा बंद रखें", "tl": "Laging nakakandado ang kuwarto"}}, {"i": "shelf", "t": {"ar": "المواد على الرفوف، لا على الأرض", "en": "Chemicals on shelves, not on floor", "ur": "کیمیکل شیلف پر، فرش پر نہیں", "bn": "রাসায়নিক তাকে রাখুন, মেঝেতে নয়", "hi": "रसायन शेल्फ पर, फर्श पर नहीं", "tl": "Kemikal sa estante, hindi sa sahig"}}, {"i": "label", "t": {"ar": "كل عبوة عليها ملصق", "en": "Every bottle has a label", "ur": "ہر بوتل پر لیبل ہو", "bn": "প্রতিটি বোতলে লেবেল থাকবে", "hi": "हर बोतल पर लेबल हो", "tl": "May label ang bawat bote"}}, {"i": "dilute", "t": {"ar": "خفف من الجهاز أو بكوب القياس فقط", "en": "Dilute only by dispenser or measuring cup", "ur": "صرف ڈسپنسر یا ناپنے والے کپ سے ملائیں", "bn": "শুধু ডিসপেনসার বা মাপার কাপে মেশান", "hi": "केवल डिस्पेंसर या माप कप से घोलें", "tl": "Tunawin gamit lang ang dispenser o panukat"}}, {"i": "mop", "t": {"ar": "اغسل الممسحات وعلّقها لتجف", "en": "Wash mops and hang to dry", "ur": "پوچے دھو کر سوکھنے کے لیے لٹکائیں", "bn": "মপ ধুয়ে শুকাতে ঝুলিয়ে রাখুন", "hi": "पोछे धोकर सूखने के लिए टांगें", "tl": "Labhan ang mop at isabit para matuyo"}}, {"i": "bucket", "t": {"ar": "فرّغ الدلاء واقلبها", "en": "Empty buckets and turn upside down", "ur": "بالٹیاں خالی کر کے الٹی رکھیں", "bn": "বালতি খালি করে উল্টে রাখুন", "hi": "बाल्टियां खाली कर उल्टी रखें", "tl": "Alisan ng tubig ang balde at itaob"}}, {"i": "colors", "t": {"ar": "خزّن كل لون منفصلاً", "en": "Store each color separately", "ur": "ہر رنگ الگ رکھیں", "bn": "প্রতিটি রঙ আলাদা রাখুন", "hi": "हर रंग अलग रखें", "tl": "Ihiwalay ang bawat kulay"}}, {"i": "cart", "t": {"ar": "نظّف العربة ورتبها يومياً", "en": "Clean and arrange the cart daily", "ur": "روزانہ ٹرالی صاف اور ترتیب دیں", "bn": "প্রতিদিন ট্রলি পরিষ্কার ও সাজান", "hi": "रोज़ ट्रॉली साफ और व्यवस्थित करें", "tl": "Linisin at ayusin ang cart araw-araw"}}], "donts": [{"i": "nofood", "t": {"ar": "لا أكل ولا أغراض شخصية", "en": "No food, no personal items", "ur": "کھانا اور ذاتی سامان منع ہے", "bn": "খাবার ও ব্যক্তিগত জিনিস নিষেধ", "hi": "खाना और निजी सामान मना है", "tl": "Bawal ang pagkain at personal na gamit"}}, {"i": "nomix", "t": {"ar": "لا تخلط المواد الكيميائية أبداً", "en": "Never mix chemicals", "ur": "کیمیکل کبھی نہ ملائیں", "bn": "কখনো রাসায়নিক মেশাবেন না", "hi": "रसायन कभी न मिलाएं", "tl": "Huwag kailanman paghaluin ang kemikal"}}, {"i": "nowet", "t": {"ar": "لا تخزن أدوات رطبة", "en": "Do not store wet tools", "ur": "گیلے اوزار نہ رکھیں", "bn": "ভেজা সরঞ্জাম রাখবেন না", "hi": "गीले औजार न रखें", "tl": "Huwag itago ang basang gamit"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C04','التنظيف اليومي للعيادات وغرف الكشف','عمالة النظافة، والتمريض للأسطح الطبية','[{"key": "purpose", "title": "الغرض والنطاق", "body": "تنظيف يومي للعيادات وغرف الكشف يركز على نقاط اللمس العالية، بالتنسيق مع التمريض في الأسطح الطبية.\n- نظام الألوان للأدوات (WI-C09): الأحمر لدورات المياه، والأزرق للمناطق العامة، والأصفر لمناطق العزل والمناطق السريرية، والأخضر لمناطق الطعام.\n- الأجهزة الطبية وأسطحها مسؤولية التمريض بحسب سياسة مكافحة العدوى، والنظافة لما حولها."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات مطاطية مناسبة للمادة الكيميائية، ونظارة عند الرش أو الخلط\n- حذاء مانع للانزلاق\n- لافتة «أرضية مبللة» قبل البدء وحتى الجفاف التام\n- قراءة بطاقة بيانات السلامة لكل مادة وعدم خلط المواد إطلاقاً (H-04)"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- قطع مايكروفايبر زرقاء (وصفراء في المناطق السريرية بحسب السياسة)\n- مطهر الأسطح المعتمد أو المناديل المشبعة\n- منظف متعادل للأرضيات (WI-C01)\n- أكياس نفايات بألوانها (S-02)"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تنظيف اليدين ولبس القفازات | — |\n| 2 | تفريغ النفايات العامة والطبية بأكياسها الصحيحة | لا خلط في الأكياس (R-31) |\n| 3 | تطهير نقاط اللمس: مقابض الأبواب، المفاتيح، المكاتب، الكراسي، لوحة المفاتيح بغطائها، الهاتف | قطعة نظيفة لكل منطقة |\n| 4 | مسح الأسطح الأفقية: الكاونتر، الرفوف، حواف النوافذ | من الأعلى للأسفل |\n| 5 | المغسلة والصنبور وموزعات الصابون والمطهر | الموزعات ممتلئة |\n| 6 | سرير الكشف وإطاره (بعد تغيير الغطاء من التمريض) | بالمطهر المعتمد |\n| 7 | الأرضية آخراً بحسب WI-C01 | جافة |\n| 8 | فحص الستارة: تُستبدل عند الاتساخ أو بحسب جدولها | تاريخ الاستبدال مسجل |\n| 9 | تسجيل التنظيف | السجل محدث |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| التنظيف اليومي | نهاية الدوام أو بداية الصباح |\n| نقاط اللمس العالية | مرتين يومياً على الأقل في العيادات المزدحمة |\n| استبدال ستائر الفصل | بحسب سياسة مكافحة العدوى، وفوراً عند التلوث |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا غبار أو بقع على الأسطح\n- النفايات مفرغة ومفروزة\n- المستهلكات ممتلئة"}, {"key": "donts", "title": "ممنوعات", "body": "- رش المطهر على الأجهزة الطبية أو الشاشات مباشرة\n- استخدام القطعة نفسها لأكثر من غرفة\n- خلط النفايات الطبية بالعامة"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01 · S-02 · R-31", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',4,'recycle','التنظيف والنظافة','GEN','["فرز النفايات وتفريغها", "تطهير نقاط اللمس", "الأسطح الأفقية", "المغسلة والموزعات", "سرير الكشف", "الأرضية", "حالة الستارة", "السجل"]'::jsonb,'{"ppe": ["gloves"], "steps": [{"i": "handwash", "t": {"ar": "نظّف يديك والبس القفازات", "en": "Clean hands and wear gloves", "ur": "ہاتھ صاف کریں اور دستانے پہنیں", "bn": "হাত পরিষ্কার করে গ্লাভস পরুন", "hi": "हाथ साफ करें और दस्ताने पहनें", "tl": "Maghugas ng kamay at magsuot ng guwantes"}}, {"i": "bag", "t": {"ar": "فرّغ النفايات كل نوع في كيسه", "en": "Empty waste, each type in its bag", "ur": "ہر قسم کا کچرا اپنے تھیلے میں", "bn": "প্রতিটি বর্জ্য নিজ ব্যাগে", "hi": "हर कचरा अपने थैले में", "tl": "Bawat basura sa sariling supot"}}, {"i": "hand", "t": {"ar": "طهّر المقابض والمكاتب والكراسي", "en": "Disinfect handles, desks and chairs", "ur": "ہینڈل، میز اور کرسیاں جراثیم سے پاک کریں", "bn": "হ্যান্ডেল, টেবিল ও চেয়ার জীবাণুমুক্ত করুন", "hi": "हैंडल, मेज और कुर्सियां कीटाणुरहित करें", "tl": "I-disinfect ang hawakan, mesa at upuan"}}, {"i": "cloth", "t": {"ar": "امسح الأسطح من الأعلى للأسفل", "en": "Wipe surfaces top to bottom", "ur": "سطحیں اوپر سے نیچے صاف کریں", "bn": "ওপর থেকে নিচে সব জায়গা মুছুন", "hi": "सतहें ऊपर से नीचे पोंछें", "tl": "Punasan mula taas pababa"}}, {"i": "sink", "t": {"ar": "المغسلة والموزعات", "en": "Sink and dispensers", "ur": "سنک اور ڈسپنسر", "bn": "বেসিন ও ডিসপেনসার", "hi": "सिंक और डिस्पेंसर", "tl": "Lababo at dispenser"}}, {"i": "bed", "t": {"ar": "سرير الكشف بالمطهر", "en": "Exam bed with disinfectant", "ur": "معائنے کا بستر جراثیم کش سے", "bn": "পরীক্ষার বেড জীবাণুনাশক দিয়ে", "hi": "जांच बिस्तर कीटाणुनाशक से", "tl": "Kama ng pagsusuri gamit ang disinfectant"}}, {"i": "mop", "t": {"ar": "الأرضية آخراً", "en": "Floor last", "ur": "فرش آخر میں", "bn": "মেঝে শেষে", "hi": "फर्श आखिर में", "tl": "Sahig ang huli"}}, {"i": "clipboard", "t": {"ar": "سجّل التنظيف", "en": "Record the cleaning", "ur": "صفائی کا اندراج کریں", "bn": "পরিষ্কারের রেকর্ড লিখুন", "hi": "सफाई दर्ज करें", "tl": "Itala ang paglilinis"}}], "donts": [{"i": "nospray", "t": {"ar": "لا ترش على الأجهزة الطبية", "en": "Do not spray medical devices", "ur": "طبی آلات پر اسپرے نہ کریں", "bn": "চিকিৎসা যন্ত্রে স্প্রে করবেন না", "hi": "चिकित्सा उपकरणों पर स्प्रे न करें", "tl": "Huwag mag-spray sa medikal na kagamitan"}}, {"i": "nocloth", "t": {"ar": "لا تستخدم القطعة نفسها لغرفتين", "en": "One cloth per room", "ur": "ایک کپڑا ایک کمرے کے لیے", "bn": "এক রুমে এক কাপড়", "hi": "एक कपड़ा एक कमरे के लिए", "tl": "Isang basahan bawat kuwarto"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C05','التنظيف النهائي لغرف العزل والإجراءات','عمالة النظافة المدربة، بإشراف مكافحة العدوى','[{"key": "purpose", "title": "الغرض والنطاق", "body": "التنظيف النهائي (Terminal Cleaning) يُنفذ عند خروج مريض العزل أو بعد الإجراءات الملوثة، ويعيد الغرفة آمنة للمريض التالي. يُنفذ وفق سياسة مكافحة العدوى في المنشأة، وهذه التعليمات تكملها ولا تحل محلها."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- معدات الوقاية بحسب نوع العزل الذي تحدده مكافحة العدوى (رداء، قفازات، كمامة مناسبة، واقي عين)\n- لبس المعدات وخلعها بالترتيب الصحيح عند الباب\n- التخلص من النفايات كنفايات طبية"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- أدوات مخصصة للعزل (صفراء) أو أحادية الاستخدام\n- المطهر الذي تحدده مكافحة العدوى لنوع العزل\n- أكياس النفايات الطبية وأكياس المغسلة الخاصة بالمعدي"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | التنسيق مع التمريض ومكافحة العدوى ووضع لافتة الغرفة | نوع العزل معروف |\n| 2 | لبس معدات الوقاية | بالترتيب الصحيح |\n| 3 | إزالة النفايات والمفروشات والستائر في أكياسها الخاصة | لا هز للمفروشات |\n| 4 | تنظيف ثم تطهير كل الأسطح من الأعلى للأسفل ومن الأنظف للأكثر تلوثاً، بما فيها الجدران القريبة ورأس السرير | مدة التلامس محترمة |\n| 5 | السرير والمرتبة (فحص سلامة الغطاء) والطاولات والخزائن | المرتبة المثقوبة تُبلّغ |\n| 6 | دورة المياه بحسب WI-C02 بأدوات منفصلة | — |\n| 7 | الأرضية آخراً | — |\n| 8 | تركيب ستائر نظيفة وتجديد المستهلكات | — |\n| 9 | خلع معدات الوقاية عند الخروج وتنظيف اليدين | بالترتيب الصحيح |\n| 10 | إبلاغ التمريض بجاهزية الغرفة وتسجيلها | تُعاد الغرفة للتشغيل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| التنظيف النهائي | عند خروج كل مريض عزل، وبعد كل إجراء ملوث |\n| مراجعة الطريقة مع مكافحة العدوى | سنوياً، وعند أي فاشية |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل الأسطح نظيفة ومطهرة\n- ستائر ومستهلكات جديدة\n- تأكيد التمريض واستلام الغرفة"}, {"key": "donts", "title": "ممنوعات", "body": "- دخول الغرفة دون معدات الوقاية المطلوبة\n- إخراج أدوات العزل لاستخدامها في غرف أخرى\n- استعجال إعادة الغرفة قبل انقضاء مدة التلامس"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01 · S-02", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',5,'recycle','التنظيف والنظافة','GEN','["التنسيق ونوع العزل", "معدات الوقاية", "إزالة النفايات والمفروشات والستائر", "تطهير الأسطح كاملة", "السرير والمرتبة", "دورة المياه", "الأرضية", "ستائر ومستهلكات جديدة", "إبلاغ التمريض"]'::jsonb,'{"ppe": ["gown", "gloves", "mask", "goggles"], "steps": [{"i": "phone", "t": {"ar": "نسّق مع التمريض واعرف نوع العزل", "en": "Ask nursing the isolation type", "ur": "نرسنگ سے آئسولیشن کی قسم پوچھیں", "bn": "নার্সের কাছে আইসোলেশনের ধরন জানুন", "hi": "नर्सिंग से आइसोलेशन का प्रकार पूछें", "tl": "Itanong sa nurse ang uri ng isolation"}}, {"i": "gown", "t": {"ar": "البس معدات الوقاية بالترتيب", "en": "Put on protective equipment in order", "ur": "حفاظتی سامان ترتیب سے پہنیں", "bn": "সুরক্ষা সরঞ্জাম ক্রমমতো পরুন", "hi": "सुरक्षा उपकरण क्रम से पहनें", "tl": "Isuot ang proteksyon nang sunod-sunod"}}, {"i": "bag", "t": {"ar": "أزل النفايات والمفروشات في أكياسها", "en": "Remove waste and linen in their bags", "ur": "کچرا اور چادریں اپنے تھیلوں میں نکالیں", "bn": "বর্জ্য ও চাদর নিজ ব্যাগে সরান", "hi": "कचरा और चादरें अपने थैलों में निकालें", "tl": "Alisin ang basura at linen sa supot nila"}}, {"i": "spray", "t": {"ar": "طهّر كل الأسطح من الأعلى للأسفل", "en": "Disinfect all surfaces top to bottom", "ur": "تمام سطحیں اوپر سے نیچے جراثیم سے پاک کریں", "bn": "সব জায়গা ওপর থেকে নিচে জীবাণুমুক্ত করুন", "hi": "सभी सतहें ऊपर से नीचे कीटाणुरहित करें", "tl": "I-disinfect lahat mula taas pababa"}}, {"i": "bed", "t": {"ar": "السرير والمرتبة والطاولات", "en": "Bed, mattress and tables", "ur": "بستر، گدا اور میزیں", "bn": "বেড, তোশক ও টেবিল", "hi": "बिस्तर, गद्दा और मेज़", "tl": "Kama, kutson at mesa"}}, {"i": "toilet", "t": {"ar": "دورة المياه بأدوات منفصلة", "en": "Toilet with separate tools", "ur": "ٹوائلٹ الگ اوزاروں سے", "bn": "আলাদা সরঞ্জামে টয়লেট", "hi": "शौचालय अलग औजारों से", "tl": "CR gamit ang hiwalay na gamit"}}, {"i": "mop", "t": {"ar": "الأرضية آخراً", "en": "Floor last", "ur": "فرش آخر میں", "bn": "মেঝে শেষে", "hi": "फर्श आखिर में", "tl": "Sahig ang huli"}}, {"i": "handwash", "t": {"ar": "اخلع المعدات عند الباب ونظف يديك", "en": "Remove equipment at door, clean hands", "ur": "دروازے پر سامان اتاریں، ہاتھ صاف کریں", "bn": "দরজায় সরঞ্জাম খুলে হাত পরিষ্কার করুন", "hi": "दरवाजे पर उपकरण उतारें, हाथ साफ करें", "tl": "Hubarin sa pinto, maghugas ng kamay"}}, {"i": "check", "t": {"ar": "أبلغ التمريض بجاهزية الغرفة", "en": "Tell nursing the room is ready", "ur": "نرسنگ کو بتائیں کمرہ تیار ہے", "bn": "নার্সকে জানান রুম প্রস্তুত", "hi": "नर्सिंग को बताएं कमरा तैयार है", "tl": "Sabihin sa nurse na handa na ang kuwarto"}}], "donts": [{"i": "noentry", "t": {"ar": "لا دخول بدون معدات الوقاية", "en": "No entry without protection", "ur": "حفاظتی سامان کے بغیر داخلہ منع", "bn": "সুরক্ষা ছাড়া প্রবেশ নিষেধ", "hi": "सुरक्षा के बिना प्रवेश मना", "tl": "Bawal pumasok nang walang proteksyon"}}, {"i": "nocloth", "t": {"ar": "لا تُخرج أدوات العزل لغرف أخرى", "en": "Do not take isolation tools out", "ur": "آئسولیشن کے اوزار باہر نہ لے جائیں", "bn": "আইসোলেশনের সরঞ্জাম বাইরে নেবেন না", "hi": "आइसोलेशन के औजार बाहर न ले जाएं", "tl": "Huwag ilabas ang gamit sa isolation"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C06','التعامل مع انسكاب الدم وسوائل الجسم','عمالة النظافة والتمريض','[{"key": "purpose", "title": "الغرض والنطاق", "body": "انسكاب الدم أو سوائل الجسم يُعامل فوراً كخطر عدوى. هذه التعليمات للانسكاب البيولوجي؛ الانسكاب الكيميائي له إجراء المواد الخطرة (H-04)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات، رداء، وواقي عين إن احتمل الرذاذ\n- لا التقاط للزجاج المكسور باليد؛ ملقط أو مجرفة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- طقم الانسكاب البيولوجي (مسحوق ماص أو مناشف، مجرفة، أكياس نفايات طبية، لافتة)\n- المطهر المعتمد للانسكابات"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | عزل المنطقة ووضع اللافتة | لا مرور |\n| 2 | لبس معدات الوقاية | — |\n| 3 | تغطية الانسكاب بالمادة الماصة أو المناشف | من الأطراف للوسط |\n| 4 | إزالة المادة والزجاج بالمجرفة في كيس النفايات الطبية أو حاوية الحادة | — |\n| 5 | تطهير المنطقة بالمطهر المعتمد ومدة التلامس | — |\n| 6 | التنظيف العادي بعدها وتجفيف المكان | — |\n| 7 | خلع المعدات وتنظيف اليدين، وإبلاغ المشرف | أي تعرض للجلد أو العين يُبلَّغ فوراً (H-03) |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| توفر طقم الانسكاب في كل طابق | فحص شهري |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا بقايا مرئية\n- المكان جاف ومطهر\n- النفايات في الكيس الصحيح"}, {"key": "donts", "title": "ممنوعات", "body": "- المسح المباشر بالممسحة دون مادة ماصة\n- التقاط الزجاج باليد\n- تأخير الإبلاغ عن أي تعرض"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-02 · H-03 · H-04", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',6,'alert','التنظيف والنظافة','GEN','["عزل المنطقة", "معدات الوقاية", "المادة الماصة", "إزالة البقايا والزجاج بأمان", "التطهير بمدة التلامس", "تنظيف وتجفيف", "الإبلاغ"]'::jsonb,'{"ppe": ["gloves", "gown", "goggles"], "steps": [{"i": "sign", "t": {"ar": "اعزل المكان وضع اللافتة", "en": "Close off the area, place the sign", "ur": "جگہ بند کریں اور بورڈ لگائیں", "bn": "জায়গা আটকে সাইন রাখুন", "hi": "जगह बंद करें और बोर्ड लगाएं", "tl": "Harangan ang lugar, ilagay ang karatula"}}, {"i": "gloves", "t": {"ar": "البس القفازات والرداء", "en": "Wear gloves and gown", "ur": "دستانے اور گاؤن پہنیں", "bn": "গ্লাভস ও গাউন পরুন", "hi": "दस्ताने और गाउन पहनें", "tl": "Magsuot ng guwantes at gown"}}, {"i": "absorb", "t": {"ar": "غطِّ الانسكاب بالمادة الماصة", "en": "Cover the spill with absorbent", "ur": "گرے ہوئے مواد کو جاذب سے ڈھانپیں", "bn": "শোষক দিয়ে ছিটানো জায়গা ঢাকুন", "hi": "फैलाव को सोखने वाली चीज़ से ढकें", "tl": "Takpan ng absorbent ang natapon"}}, {"i": "scoop", "t": {"ar": "ارفعه بالمجرفة، لا باليد", "en": "Pick up with scoop, not hand", "ur": "ہاتھ سے نہیں، اسکوپ سے اٹھائیں", "bn": "হাতে নয়, স্কুপ দিয়ে তুলুন", "hi": "हाथ से नहीं, स्कूप से उठाएं", "tl": "Damputin gamit ang scoop, hindi kamay"}}, {"i": "spray", "t": {"ar": "طهّر المكان واترك المطهر المدة المحددة", "en": "Disinfect and wait the contact time", "ur": "جراثیم کش لگائیں اور وقت انتظار کریں", "bn": "জীবাণুনাশক দিয়ে সময় অপেক্ষা করুন", "hi": "कीटाणुनाशक लगाएं और समय रुकें", "tl": "Mag-disinfect at hintayin ang oras"}}, {"i": "phone", "t": {"ar": "أبلغ المشرف فوراً", "en": "Tell the supervisor now", "ur": "فوراً سپروائزر کو بتائیں", "bn": "এখনই সুপারভাইজারকে জানান", "hi": "तुरंत सुपरवाइज़र को बताएं", "tl": "Sabihan agad ang supervisor"}}], "donts": [{"i": "noglass", "t": {"ar": "لا تلتقط الزجاج باليد", "en": "Never pick up glass by hand", "ur": "شیشہ ہاتھ سے نہ اٹھائیں", "bn": "হাতে কাচ তুলবেন না", "hi": "कांच हाथ से न उठाएं", "tl": "Huwag damputin ng kamay ang bubog"}}, {"i": "nomop", "t": {"ar": "لا تمسح مباشرة بالممسحة", "en": "Do not mop directly", "ur": "سیدھا پوچا نہ لگائیں", "bn": "সরাসরি মপ দেবেন না", "hi": "सीधे पोछा न लगाएं", "tl": "Huwag i-mop nang direkta"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C07','تنظيف الواجهات الزجاجية واللوحات والإرشاد','عمالة النظافة ومقاول تنظيف الواجهات','[{"key": "purpose", "title": "الغرض والنطاق", "body": "اللوحات والواجهات أول ما يراه المراجع من هوية التجمع. التنظيف الخاطئ يخدش الأكريليك ويطفئ الإضاءة ويُسقط الحروف."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- العمل على ارتفاع بمعدات معتمدة وتصريح عمل (M-01، R-13)\n- فصل الكهرباء عن اللوحات المضيئة بالتنسيق مع الصيانة قبل التنظيف المبلل"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- ماء منزوع المعادن أو منظف زجاج خفيف\n- قطع مايكروفايبر ناعمة ومسّاحات مطاطية\n- منظف خاص بالأكريليك للوحات"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | إزالة الغبار بالفرشاة الناعمة أو الهواء | بلا خدش |\n| 2 | الزجاج: منظف خفيف ثم المسّاحة المطاطية من الأعلى للأسفل | بلا خطوط |\n| 3 | اللوحات والحروف المضيئة: قطعة مايكروفايبر ومنظف الأكريليك، بلا ضغط | الحروف ثابتة |\n| 4 | إزالة الملصقات المخالفة دون شفرات على الأكريليك | بلا آثار |\n| 5 | فحص الإضاءة والحروف والإبلاغ عن أي تلف | بلاغ برمز الموقع |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الزجاج الأرضي والمداخل | يومياً |\n| الواجهات المرتفعة | ربع سنوياً أو حسب العقد |\n| اللوحات الخارجية | شهرياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- زجاج بلا خطوط أو بقع\n- لوحات نظيفة مضيئة بلا حروف ناقصة"}, {"key": "donts", "title": "ممنوعات", "body": "- المواد الكاشطة أو الكحول المركز أو الأمونيا على الأكريليك\n- الشفرات على اللوحات\n- التنظيف المبلل للوحة مضيئة موصولة بالكهرباء"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01 · M-01", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',7,'recycle','التنظيف والنظافة','GEN','["تصريح العمل على ارتفاع", "فصل الكهرباء عن اللوحات المضيئة", "الزجاج بلا خطوط", "اللوحات بمنظف الأكريليك", "إزالة الملصقات المخالفة", "فحص الإضاءة والحروف"]'::jsonb,'{"ppe": ["gloves", "harness"], "steps": [{"i": "power", "t": {"ar": "افصل كهرباء اللوحة المضيئة أولاً", "en": "Switch off lit signs first", "ur": "روشن بورڈ کی بجلی پہلے بند کریں", "bn": "আলোকিত সাইনের বিদ্যুৎ আগে বন্ধ করুন", "hi": "रोशनी वाले बोर्ड की बिजली पहले बंद करें", "tl": "Patayin muna ang kuryente ng ilaw ng karatula"}}, {"i": "ladder", "t": {"ar": "العمل على ارتفاع بتصريح وسلّم معتمد", "en": "Work at height with permit and approved ladder", "ur": "اونچائی پر پرمٹ اور منظور سیڑھی سے", "bn": "উচ্চতায় অনুমতি ও অনুমোদিত মই দিয়ে", "hi": "ऊंचाई पर परमिट और मंज़ूर सीढ़ी से", "tl": "Sa mataas: may permit at aprubadong hagdan"}}, {"i": "cloth", "t": {"ar": "أزل الغبار بقطعة ناعمة", "en": "Remove dust with soft cloth", "ur": "نرم کپڑے سے دھول ہٹائیں", "bn": "নরম কাপড়ে ধুলো সরান", "hi": "मुलायम कपड़े से धूल हटाएं", "tl": "Alisin ang alikabok gamit ang malambot na tela"}}, {"i": "squeegee", "t": {"ar": "الزجاج بالمسّاحة من الأعلى للأسفل", "en": "Glass with squeegee, top to bottom", "ur": "شیشہ وائپر سے اوپر سے نیچے", "bn": "কাচ ওয়াইপার দিয়ে ওপর থেকে নিচে", "hi": "कांच वाइपर से ऊपर से नीचे", "tl": "Salamin gamit ang squeegee, taas pababa"}}, {"i": "wrench", "t": {"ar": "أبلغ عن أي حرف ناقص أو إضاءة معطلة", "en": "Report missing letters or broken lights", "ur": "غائب حروف یا خراب روشنی بتائیں", "bn": "হারানো অক্ষর বা নষ্ট আলো জানান", "hi": "गायब अक्षर या खराब रोशनी बताएं", "tl": "I-report ang nawawalang letra o sirang ilaw"}}], "donts": [{"i": "noscrape", "t": {"ar": "لا شفرات ولا مواد كاشطة على اللوحات", "en": "No blades or abrasives on signs", "ur": "بورڈ پر بلیڈ یا رگڑنے والا مواد منع", "bn": "সাইনে ব্লেড বা ঘষা জিনিস নিষেধ", "hi": "बोर्ड पर ब्लेड या घिसने वाली चीज़ मना", "tl": "Bawal ang blade o pangkuskos sa karatula"}}, {"i": "nosticker", "t": {"ar": "لا ملصقات على اللوحات والزجاج", "en": "No stickers on signs or glass", "ur": "بورڈ اور شیشے پر اسٹیکر منع", "bn": "সাইন ও কাচে স্টিকার নিষেধ", "hi": "बोर्ड और कांच पर स्टिकर मना", "tl": "Bawal ang sticker sa karatula at salamin"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C08','جمع النفايات ونقلها داخل المنشأة','عمالة النظافة وناقلو النفايات','[{"key": "purpose", "title": "الغرض والنطاق", "body": "فرز النفايات يبدأ عند مصدرها (R-31)، ودور عامل النظافة جمعها ونقلها دون خلط أو تسرب إلى غرفة التخزين المؤقت، حتى تسليمها لمقاول النقل المرخص (S-02)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات سميكة وحذاء مغلق\n- لا ضغط للأكياس باليد أو بالقدم\n- التطعيمات المطلوبة لناقلي النفايات الطبية بحسب سياسة المنشأة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- عربات مغلقة منفصلة للنفايات الطبية والعامة\n- أكياس بألوانها وحاويات الحادة\n- أربطة وملصقات المصدر والتاريخ"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | إغلاق الكيس عند امتلائه ثلاثة أرباعه بالربط لا بالعقد المفتوح | لا كيس ممتلئ أكثر من ذلك |\n| 2 | حاويات الحادة تُغلق عند خط الامتلاء | لا شيء فوق الخط |\n| 3 | وضع ملصق القسم والتاريخ على النفايات الطبية | المصدر معروف |\n| 4 | النقل في العربة المخصصة لكل نوع، مغلقة، وفي المسار والأوقات المحددة بعيداً عن المرضى والطعام | لا حمل باليد |\n| 5 | التخزين المؤقت في غرفة مقفلة مبردة أو مهواة بحسب النوع | لا تخزين خارج الغرفة |\n| 6 | غسل العربات وتطهيرها بعد كل جولة | — |\n| 7 | تسليم النفايات الطبية للمقاول بوثيقة شحن موقعة | الوثيقة محفوظة |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| جمع النفايات من الأقسام | مرتين يومياً على الأقل، وعند الامتلاء |\n| تسليم النفايات الطبية للمقاول | بحسب الجدول التعاقدي |\n| تنظيف غرفة التخزين المؤقت | يومياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا أكياس مفتوحة أو متسربة\n- لا خلط بين الأنواع\n- وثائق الشحن مكتملة"}, {"key": "donts", "title": "ممنوعات", "body": "- نقل النفايات في مصاعد المرضى أو مع الطعام\n- إعادة فتح الأكياس أو نقل المحتوى بين الأكياس\n- ترك النفايات في الممرات"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-02 · R-31", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',8,'recycle','التنظيف والنظافة','GEN','["الأكياس مغلقة عند ثلاثة أرباعها", "حاويات الحادة عند الخط", "ملصق المصدر", "العربة المخصصة والمسار المحدد", "التخزين المؤقت", "تطهير العربات", "وثيقة الشحن"]'::jsonb,'{"ppe": ["gloves", "boots"], "steps": [{"i": "bag", "t": {"ar": "اربط الكيس عند ثلاثة أرباعه", "en": "Tie the bag at three-quarters full", "ur": "تھیلا تین چوتھائی پر باندھیں", "bn": "ব্যাগ তিন-চতুর্থাংশ ভরলে বাঁধুন", "hi": "थैला तीन-चौथाई भरने पर बांधें", "tl": "Talian ang supot kapag 3/4 na"}}, {"i": "sharps", "t": {"ar": "حاوية الحادة تُغلق عند الخط", "en": "Close sharps box at the line", "ur": "شارپس باکس لائن پر بند کریں", "bn": "শার্পস বাক্স দাগে বন্ধ করুন", "hi": "शार्प्स बॉक्स लाइन पर बंद करें", "tl": "Isara ang sharps box sa linya"}}, {"i": "label", "t": {"ar": "ضع ملصق القسم والتاريخ", "en": "Label department and date", "ur": "شعبہ اور تاریخ کا لیبل لگائیں", "bn": "বিভাগ ও তারিখের লেবেল দিন", "hi": "विभाग और तारीख का लेबल लगाएं", "tl": "Lagyan ng label ang departamento at petsa"}}, {"i": "cart", "t": {"ar": "انقل بالعربة المغلقة في المسار المحدد", "en": "Move in closed cart on set route", "ur": "بند ٹرالی میں مقررہ راستے سے لے جائیں", "bn": "বন্ধ ট্রলিতে নির্দিষ্ট পথে নিন", "hi": "बंद ट्रॉली में तय रास्ते से ले जाएं", "tl": "Dalhin sa saradong cart sa takdang ruta"}}, {"i": "lock", "t": {"ar": "خزّن في غرفة النفايات المقفلة", "en": "Store in the locked waste room", "ur": "بند کچرا کمرے میں رکھیں", "bn": "তালাবদ্ধ বর্জ্য কক্ষে রাখুন", "hi": "बंद कचरा कमरे में रखें", "tl": "Itago sa nakakandadong silid ng basura"}}, {"i": "spray", "t": {"ar": "اغسل العربة وطهّرها", "en": "Wash and disinfect the cart", "ur": "ٹرالی دھو کر جراثیم سے پاک کریں", "bn": "ট্রলি ধুয়ে জীবাণুমুক্ত করুন", "hi": "ट्रॉली धोकर कीटाणुरहित करें", "tl": "Hugasan at i-disinfect ang cart"}}], "donts": [{"i": "noelevator", "t": {"ar": "لا نفايات في مصاعد المرضى", "en": "No waste in patient elevators", "ur": "مریضوں کی لفٹ میں کچرا منع", "bn": "রোগীর লিফটে বর্জ্য নিষেধ", "hi": "मरीज़ों की लिफ्ट में कचरा मना", "tl": "Bawal ang basura sa elevator ng pasyente"}}, {"i": "nopress", "t": {"ar": "لا تضغط الأكياس بيدك أو قدمك", "en": "Never press bags with hand or foot", "ur": "تھیلے ہاتھ یا پاؤں سے نہ دبائیں", "bn": "ব্যাগ হাত বা পা দিয়ে চাপবেন না", "hi": "थैले हाथ या पैर से न दबाएं", "tl": "Huwag diinan ang supot ng kamay o paa"}}, {"i": "nomix_bag", "t": {"ar": "لا تخلط أنواع النفايات", "en": "Do not mix waste types", "ur": "کچرے کی اقسام نہ ملائیں", "bn": "বর্জ্যের ধরন মেশাবেন না", "hi": "कचरे के प्रकार न मिलाएं", "tl": "Huwag paghaluin ang uri ng basura"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-C09','نظام الألوان لأدوات التنظيف','كل عمالة النظافة ومشرفيها','[{"key": "purpose", "title": "الغرض والنطاق", "body": "أداة تنظيف دورة المياه لا يجوز أن تلمس طاولة طعام أو سرير مريض. نظام الألوان يجعل ذلك واضحاً لكل عامل مهما كانت لغته."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- الالتزام بالألوان شرط في عقد النظافة (S-01)"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- قطع مايكروفايبر وممسحات ودلاء وقفازات بأربعة ألوان\n- ملصق النظام معلق في كل غرفة جانيتور"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | الأحمر: دورات المياه والمراحيض والمباول وأرضياتها | لا يُستخدم خارجها |\n| 2 | الأزرق: المناطق العامة والمكاتب والممرات والانتظار | — |\n| 3 | الأصفر: مناطق العزل والمناطق السريرية بحسب سياسة مكافحة العدوى | — |\n| 4 | الأخضر: المطابخ ومناطق تحضير الطعام وتقديمه | — |\n| 5 | غسل وتخزين كل لون منفصلاً (WI-C03) | لا اختلاط في الغسيل والتخزين |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| تدريب العمالة الجديدة | قبل البدء بالعمل |\n| تفتيش الالتزام | أسبوعياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل عامل يعرف الألوان\n- لا أداة بلون خاطئ في أي منطقة"}, {"key": "donts", "title": "ممنوعات", "body": "- استخدام لون في غير منطقته\n- غسل الألوان معاً"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "S-01", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',9,'recycle','التنظيف والنظافة','GEN','["الأحمر في دورات المياه فقط", "الأزرق للعامة", "الأصفر للعزل والسريرية", "الأخضر للطعام", "التخزين المنفصل"]'::jsonb,'{"ppe": ["gloves"], "steps": [{"i": "red", "t": {"ar": "الأحمر: دورات المياه فقط", "en": "RED: toilets only", "ur": "سرخ: صرف ٹوائلٹ", "bn": "লাল: শুধু টয়লেট", "hi": "लाल: सिर्फ शौचालय", "tl": "PULA: CR lamang"}}, {"i": "blue", "t": {"ar": "الأزرق: المكاتب والممرات والانتظار", "en": "BLUE: offices, corridors, waiting", "ur": "نیلا: دفاتر، راہداریاں، انتظار گاہ", "bn": "নীল: অফিস, করিডোর, অপেক্ষা কক্ষ", "hi": "नीला: दफ्तर, गलियारे, प्रतीक्षा", "tl": "ASUL: opisina, pasilyo, hintayan"}}, {"i": "yellow", "t": {"ar": "الأصفر: العزل والمناطق الطبية", "en": "YELLOW: isolation and clinical areas", "ur": "پیلا: آئسولیشن اور طبی جگہیں", "bn": "হলুদ: আইসোলেশন ও চিকিৎসা এলাকা", "hi": "पीला: आइसोलेशन और चिकित्सा क्षेत्र", "tl": "DILAW: isolation at klinikal na lugar"}}, {"i": "green", "t": {"ar": "الأخضر: المطبخ والطعام", "en": "GREEN: kitchen and food", "ur": "سبز: کچن اور کھانا", "bn": "সবুজ: রান্নাঘর ও খাবার", "hi": "हरा: रसोई और खाना", "tl": "BERDE: kusina at pagkain"}}, {"i": "colors", "t": {"ar": "اغسل وخزّن كل لون منفصلاً", "en": "Wash and store each color separately", "ur": "ہر رنگ الگ دھوئیں اور رکھیں", "bn": "প্রতিটি রঙ আলাদা ধুয়ে রাখুন", "hi": "हर रंग अलग धोएं और रखें", "tl": "Labhan at itago nang hiwalay ang bawat kulay"}}], "donts": [{"i": "nocolor", "t": {"ar": "لا تستخدم لوناً في غير مكانه", "en": "Never use a color in the wrong area", "ur": "غلط جگہ پر رنگ استعمال نہ کریں", "bn": "ভুল জায়গায় রঙ ব্যবহার করবেন না", "hi": "गलत जगह रंग इस्तेमाल न करें", "tl": "Huwag gamitin ang kulay sa maling lugar"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M01','الصيانة الدورية للمكيفات الجدارية (سبليت)','فنيو التكييف ومقاول التشغيل والصيانة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "صيانة المكيفات المنفصلة الجدارية (سبليت) والكاسيت والأرضية-السقفية. في مناخ الأحساء (غبار وحرارة عالية) تتسخ الفلاتر والمكثفات أسرع، فالتكرار هنا أعلى من المعتاد في أدلة الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عزل الكهرباء عن الوحدة بالقفل والبطاقة والتحقق من انعدام الجهد قبل فتحها (M-01)\n- العمل على ارتفاع بسلم أو منصة معتمدة\n- التعامل مع وسيط التبريد بفني مؤهل وقفازات ونظارة، ولا يُطلق للجو\n- نظارة وكمامة عند تنظيف الملفات بالمواد أو الهواء المضغوط"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- أدوات يدوية ومقياس متعدد وأمبير كلّابي\n- عدادات ضغط (مانيفولد) ومقياس حرارة\n- رشاش ماء منخفض الضغط ومنظف ملفات معتمد (غير حمضي للألمنيوم)\n- غطاء تنظيف الوحدة الداخلية وحوض تجميع\n- فلاتر بديلة إن لزم"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تسجيل حالة الوحدة قبل البدء (يعمل/لا يعمل، الشكوى، القراءات) | القراءات مسجلة |\n| 2 | فصل الكهرباء وعزلها | انعدام الجهد مؤكد |\n| 3 | فك الفلاتر وغسلها بالماء وتجفيفها في الظل، أو استبدالها إن تلفت | فلتر نظيف جاف |\n| 4 | تنظيف الملف الداخلي بالمنظف المعتمد والشطف بالغطاء والحوض | لا اتساخ في الزعانف ولا ماء على الجدار |\n| 5 | تنظيف المروحة الأسطوانية والغطاء والشفرات | بلا عفن أو أوساخ |\n| 6 | تنظيف حوض التكثيف وفحص خط التصريف بصب الماء | التصريف حر بلا تسرب |\n| 7 | الوحدة الخارجية: تنظيف المكثف من الغبار والأوساخ بالماء من الداخل للخارج | الزعانف نظيفة ومستقيمة |\n| 8 | فحص المروحة الخارجية وتثبيتها والأسلاك والتوصيلات | لا ارتخاء أو احتراق |\n| 9 | إعادة التشغيل وقياس التيار ودرجة حرارة الهواء الخارج والداخل | فرق الحرارة ضمن المعتاد للوحدة |\n| 10 | قياس الضغوط عند الاشتباه بنقص وسيط التبريد، والبحث عن التسرب قبل الإضافة | لا إضافة بلا إصلاح التسرب |\n| 11 | فحص الريموت والثرموستات والإعداد المحدد | الإعداد بحسب سياسة المنشأة |\n| 12 | تنظيف المكان وإغلاق أمر العمل بالقراءات والصور | قبل وبعد |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| تنظيف الفلاتر | شهرياً، وكل أسبوعين في المناطق المغبرة والحرجة |\n| تنظيف الملف الداخلي والمروحة وحوض التكثيف | كل 3 أشهر |\n| تنظيف المكثف الخارجي | كل 3 أشهر، وقبل الصيف (K-08) |\n| فحص كهربائي وقياس التيار والضغوط | كل 6 أشهر |"}, {"key": "accept", "title": "معايير القبول", "body": "- الوحدة تبرد ضمن المعتاد بلا أصوات أو اهتزاز\n- لا تسرب ماء داخلي\n- القراءات مسجلة في المنصة"}, {"key": "donts", "title": "ممنوعات", "body": "- تشغيل المكيف بلا فلتر\n- رش الماء على الوحدة الداخلية دون غطاء أو والكهرباء موصولة\n- إضافة وسيط تبريد دون كشف التسرب\n- المنظفات الحمضية على زعانف الألمنيوم\n- إطلاق وسيط التبريد في الجو"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "G-06 · M-01 · PL-06 · K-08", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',10,'wrench','التكييف','MNT','["تسجيل القراءات قبل البدء", "عزل الكهرباء", "غسل الفلاتر أو استبدالها", "تنظيف الملف الداخلي", "تنظيف المروحة والغطاء", "حوض التكثيف وخط التصريف", "تنظيف المكثف الخارجي", "فحص التوصيلات الكهربائية", "قياس التيار وفرق الحرارة", "فحص الثرموستات والإعداد", "صور قبل وبعد"]'::jsonb,'{"ppe": ["gloves", "goggles", "ladder"], "steps": [{"i": "power", "t": {"ar": "افصل الكهرباء واقفلها وتأكد من انعدامها", "en": "Isolate, lock out and test for zero power", "ur": "بجلی بند، لاک کریں اور چیک کریں", "bn": "বিদ্যুৎ বন্ধ, লক করে পরীক্ষা করুন", "hi": "बिजली बंद, लॉक करें और जांचें", "tl": "Patayin, i-lock at subukan ang kuryente"}}, {"i": "clipboard", "t": {"ar": "سجّل القراءات قبل البدء", "en": "Record readings before starting", "ur": "شروع سے پہلے ریڈنگ لکھیں", "bn": "শুরুর আগে রিডিং লিখুন", "hi": "शुरू से पहले रीडिंग लिखें", "tl": "Itala ang reading bago magsimula"}}, {"i": "filter", "t": {"ar": "اغسل الفلاتر وجففها في الظل", "en": "Wash filters, dry in shade", "ur": "فلٹر دھو کر سائے میں سکھائیں", "bn": "ফিল্টার ধুয়ে ছায়ায় শুকান", "hi": "फ़िल्टर धोकर छाया में सुखाएं", "tl": "Hugasan ang filter, patuyuin sa lilim"}}, {"i": "coil", "t": {"ar": "نظّف الملف الداخلي بالغطاء والحوض", "en": "Clean indoor coil with cover bag", "ur": "اندرونی کوائل کور کے ساتھ صاف کریں", "bn": "কভার দিয়ে ভেতরের কয়েল পরিষ্কার করুন", "hi": "कवर के साथ अंदर की कॉइल साफ करें", "tl": "Linisin ang indoor coil gamit ang cover"}}, {"i": "fan", "t": {"ar": "نظّف المروحة والغطاء", "en": "Clean blower and cover", "ur": "بلوئر اور کور صاف کریں", "bn": "ব্লোয়ার ও কভার পরিষ্কার করুন", "hi": "ब्लोअर और कवर साफ करें", "tl": "Linisin ang blower at takip"}}, {"i": "drop", "t": {"ar": "افحص حوض وخط التصريف بصب الماء", "en": "Test drain pan and line with water", "ur": "ڈرین پین اور پائپ پانی سے چیک کریں", "bn": "পানি ঢেলে ড্রেন প্যান ও পাইপ পরীক্ষা করুন", "hi": "पानी डालकर ड्रेन पैन और पाइप जांचें", "tl": "Subukan ng tubig ang drain pan at tubo"}}, {"i": "outdoor", "t": {"ar": "نظّف الوحدة الخارجية من الداخل للخارج", "en": "Clean outdoor coil from inside out", "ur": "باہر والا یونٹ اندر سے باہر کی طرف صاف کریں", "bn": "বাইরের ইউনিট ভেতর থেকে বাইরে পরিষ্কার করুন", "hi": "बाहरी यूनिट अंदर से बाहर साफ करें", "tl": "Linisin ang outdoor mula loob palabas"}}, {"i": "bolt", "t": {"ar": "افحص التوصيلات الكهربائية", "en": "Check electrical connections", "ur": "بجلی کے کنکشن چیک کریں", "bn": "বৈদ্যুতিক সংযোগ পরীক্ষা করুন", "hi": "बिजली के कनेक्शन जांचें", "tl": "Suriin ang koneksyon ng kuryente"}}, {"i": "thermo", "t": {"ar": "شغّل وقس التيار وفرق الحرارة", "en": "Run, measure current and temperature", "ur": "چلائیں، کرنٹ اور درجہ حرارت ناپیں", "bn": "চালিয়ে কারেন্ট ও তাপমাত্রা মাপুন", "hi": "चलाएं, करंट और तापमान नापें", "tl": "Paandarin, sukatin ang kuryente at temperatura"}}, {"i": "camera", "t": {"ar": "صوّر قبل وبعد وأغلق الأمر", "en": "Photo before/after, close the order", "ur": "پہلے/بعد کی تصویر لیں، آرڈر بند کریں", "bn": "আগে/পরে ছবি তুলে অর্ডার বন্ধ করুন", "hi": "पहले/बाद की फोटो लें, ऑर्डर बंद करें", "tl": "Kunan bago/pagkatapos, isara ang order"}}], "donts": [{"i": "nofilter", "t": {"ar": "لا تشغيل بدون فلتر", "en": "Never run without filter", "ur": "فلٹر کے بغیر کبھی نہ چلائیں", "bn": "ফিল্টার ছাড়া চালাবেন না", "hi": "फ़िल्टर के बिना कभी न चलाएं", "tl": "Huwag paandarin nang walang filter"}}, {"i": "nogas", "t": {"ar": "لا إضافة فريون قبل إصلاح التسرب", "en": "No refrigerant before fixing leak", "ur": "لیک ٹھیک کیے بغیر گیس نہ ڈالیں", "bn": "লিক ঠিক না করে গ্যাস দেবেন না", "hi": "लीक ठीक किए बिना गैस न डालें", "tl": "Walang refrigerant bago ayusin ang tagas"}}, {"i": "nowater_elec", "t": {"ar": "لا ماء والكهرباء موصولة", "en": "No water while power is on", "ur": "بجلی چالو ہو تو پانی نہیں", "bn": "বিদ্যুৎ চালু থাকলে পানি নয়", "hi": "बिजली चालू हो तो पानी नहीं", "tl": "Walang tubig habang may kuryente"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M02','الصيانة الدورية للوحدات المجزأة المركزية (دكت سبليت) والوحدات المجمعة (باكج)','فنيو التكييف ومقاول التشغيل والصيانة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "الوحدات المركزية المجزأة (دكت سبليت) والوحدات المجمعة على الأسطح (باكج يونت) التي تغذي أكثر من فراغ عبر مجاري الهواء."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عزل الكهرباء عن الوحدة بالقفل والبطاقة والتحقق من انعدام الجهد قبل فتحها (M-01)\n- العمل على ارتفاع بسلم أو منصة معتمدة\n- التعامل مع وسيط التبريد بفني مؤهل وقفازات ونظارة، ولا يُطلق للجو\n- نظارة وكمامة عند تنظيف الملفات بالمواد أو الهواء المضغوط\n- العمل على السطح بممرات آمنة وحماية من السقوط"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- ما في WI-M01\n- مقياس سرعة الهواء أو فرق الضغط على الفلاتر\n- سيور بديلة للمراوح ذات السيور\n- شحم للمحامل بحسب الصانع"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تسجيل القراءات والشكاوى | — |\n| 2 | عزل الكهرباء | — |\n| 3 | استبدال الفلاتر أو غسلها، وقياس فرق الضغط إن وُجد مقياس | الفلاتر ملتصقة بإطارها بلا تسريب هواء جانبي |\n| 4 | تنظيف ملف التبخير وحوض التكثيف ومعالجته، وفحص المصيدة وخط التصريف | التصريف حر |\n| 5 | مروحة الهواء: تنظيف الشفرات، فحص السير وشده أو استبداله، تشحيم المحامل | لا اهتزاز ولا صرير |\n| 6 | ملف التكثيف: تنظيف بالماء أو المنظف المعتمد من الداخل للخارج | الزعانف نظيفة |\n| 7 | الضاغط: فحص الأصوات والتوصيلات والحرارة ومسخن الزيت إن وُجد | — |\n| 8 | اللوحة الكهربائية: شد التوصيلات، فحص الكونتاكتورات والمكثفات | لا احتراق |\n| 9 | مجاري الهواء الظاهرة والفتحات: فحص العزل والتسريب، وتنظيف الفتحات | لا تكثف أو تسريب |\n| 10 | التشغيل وقياس التيار وفرق الحرارة والضغوط | ضمن قيم الصانع |\n| 11 | فحص الثرموستات وجدول التشغيل وتشغيل مخمد الهواء النقي | — |\n| 12 | إغلاق الأمر بالقراءات والصور | — |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الفلاتر | شهرياً |\n| الملفات وحوض التكثيف والسيور | كل 3 أشهر |\n| الفحص الكهربائي والقياسات | كل 3 أشهر |\n| تنظيف مجاري الهواء | بحسب الفحص، وعند التأهيل |"}, {"key": "accept", "title": "معايير القبول", "body": "- تبريد متوازن في الفراغات المخدومة\n- لا تكثف أو تسرب في الأسقف\n- القراءات مسجلة"}, {"key": "donts", "title": "ممنوعات", "body": "- تشغيل الوحدة بلا فلاتر أو بفلاتر غير محكمة\n- شد السير بأكثر من توصية الصانع\n- تجاهل الماء في حوض التكثيف"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "G-06 · M-01 · PL-06", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',11,'wrench','التكييف','MNT','["القراءات قبل البدء", "عزل الكهرباء", "الفلاتر", "ملف التبخير وحوض التكثيف", "المروحة والسير والمحامل", "ملف التكثيف", "الضاغط", "اللوحة الكهربائية", "مجاري الهواء والفتحات", "القياسات بعد التشغيل", "الثرموستات وجدول التشغيل"]'::jsonb,'{"ppe": ["gloves", "goggles", "harness"], "steps": [{"i": "power", "t": {"ar": "افصل الكهرباء واقفلها وتأكد من انعدامها", "en": "Isolate, lock out and test for zero power", "ur": "بجلی بند، لاک کریں اور چیک کریں", "bn": "বিদ্যুৎ বন্ধ, লক করে পরীক্ষা করুন", "hi": "बिजली बंद, लॉक करें और जांचें", "tl": "Patayin, i-lock at subukan ang kuryente"}}, {"i": "filter", "t": {"ar": "استبدل الفلاتر وتأكد أنها محكمة", "en": "Replace filters, check tight fit", "ur": "فلٹر بدلیں اور فٹنگ چیک کریں", "bn": "ফিল্টার বদলে ঠিকমতো বসেছে দেখুন", "hi": "फ़िल्टर बदलें और फिटिंग जांचें", "tl": "Palitan ang filter, siguraduhing sakto"}}, {"i": "coil", "t": {"ar": "نظّف ملف التبخير وحوض التكثيف", "en": "Clean evaporator coil and drain pan", "ur": "ایواپوریٹر کوائل اور ڈرین پین صاف کریں", "bn": "ইভাপোরেটর কয়েল ও ড্রেন প্যান পরিষ্কার করুন", "hi": "इवैपोरेटर कॉइल और ड्रेन पैन साफ करें", "tl": "Linisin ang evaporator coil at drain pan"}}, {"i": "belt", "t": {"ar": "افحص السير والمحامل والمروحة", "en": "Check belt, bearings and fan", "ur": "بیلٹ، بیئرنگ اور پنکھا چیک کریں", "bn": "বেল্ট, বিয়ারিং ও ফ্যান পরীক্ষা করুন", "hi": "बेल्ट, बेयरिंग और पंखा जांचें", "tl": "Suriin ang belt, bearing at bentilador"}}, {"i": "outdoor", "t": {"ar": "نظّف ملف التكثيف", "en": "Clean condenser coil", "ur": "کنڈینسر کوائل صاف کریں", "bn": "কনডেন্সার কয়েল পরিষ্কার করুন", "hi": "कंडेंसर कॉइल साफ करें", "tl": "Linisin ang condenser coil"}}, {"i": "bolt", "t": {"ar": "افحص اللوحة الكهربائية", "en": "Check the electric panel", "ur": "بجلی کا پینل چیک کریں", "bn": "বৈদ্যুতিক প্যানেল পরীক্ষা করুন", "hi": "बिजली पैनल जांचें", "tl": "Suriin ang electric panel"}}, {"i": "duct", "t": {"ar": "افحص المجاري والفتحات", "en": "Check ducts and grilles", "ur": "ڈکٹ اور جالیاں چیک کریں", "bn": "ডাক্ট ও গ্রিল পরীক্ষা করুন", "hi": "डक्ट और जाली जांचें", "tl": "Suriin ang duct at grille"}}, {"i": "thermo", "t": {"ar": "شغّل وسجّل القراءات", "en": "Run and record readings", "ur": "چلائیں اور ریڈنگ لکھیں", "bn": "চালিয়ে রিডিং লিখুন", "hi": "चलाएं और रीडिंग लिखें", "tl": "Paandarin at itala ang reading"}}], "donts": [{"i": "nofilter", "t": {"ar": "لا تشغيل بدون فلاتر", "en": "Never run without filters", "ur": "فلٹر کے بغیر نہ چلائیں", "bn": "ফিল্টার ছাড়া চালাবেন না", "hi": "फ़िल्टर के बिना न चलाएं", "tl": "Huwag paandarin nang walang filter"}}, {"i": "nodrop", "t": {"ar": "لا تترك ماء في حوض التكثيف", "en": "No standing water in drain pan", "ur": "ڈرین پین میں پانی نہ رہے", "bn": "ড্রেন প্যানে পানি জমতে দেবেন না", "hi": "ड्रेन पैन में पानी न रहे", "tl": "Walang naiipong tubig sa drain pan"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M03','الصيانة الدورية لأنظمة التدفق المتغير (VRF)','فنيو التكييف المؤهلون على نظام الصانع','[{"key": "purpose", "title": "الغرض والنطاق", "body": "أنظمة VRF وحدة خارجية واحدة أو أكثر تخدم وحدات داخلية متعددة بتحكم مركزي. الأعطال فيها تُشخص بأكواد الصانع، وأي فتح لدائرة التبريد يحتاج فنياً مؤهلاً على النظام."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عزل الكهرباء عن الوحدة بالقفل والبطاقة والتحقق من انعدام الجهد قبل فتحها (M-01)\n- العمل على ارتفاع بسلم أو منصة معتمدة\n- التعامل مع وسيط التبريد بفني مؤهل وقفازات ونظارة، ولا يُطلق للجو\n- نظارة وكمامة عند تنظيف الملفات بالمواد أو الهواء المضغوط"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- جهاز التشخيص أو برنامج الصانع\n- ما في WI-M01"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | قراءة أكواد الأعطال وسجل التشغيل من التحكم المركزي | الأعطال مسجلة |\n| 2 | عزل الكهرباء للوحدة المعنية | — |\n| 3 | الوحدات الداخلية: الفلاتر والملف وحوض التكثيف ومضخة التصريف إن وُجدت | المضخة تعمل والتصريف حر |\n| 4 | الوحدة الخارجية: تنظيف المكثف وفحص المراوح والتوصيلات | — |\n| 5 | فحص عزل الأنابيب الظاهرة وصناديق التوزيع | لا تكثف أو تلف |\n| 6 | التشغيل ومراقبة الضغوط والحرارة من التحكم بحسب الصانع | ضمن القيم |\n| 7 | فحص جدولة التحكم المركزي وحدود الإعدادات | بحسب سياسة المنشأة |\n| 8 | تسجيل القراءات والأكواد وإغلاق الأمر | — |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| فلاتر الوحدات الداخلية | شهرياً |\n| ملفات الوحدات الداخلية ومضخات التصريف | كل 3 أشهر |\n| الوحدات الخارجية | كل 3 أشهر |\n| الفحص الشامل بالتشخيص | كل 6 أشهر، أو بحسب عقد الوكيل |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا أكواد أعطال قائمة\n- كل الوحدات الداخلية تعمل وتصرف\n- القراءات مسجلة"}, {"key": "donts", "title": "ممنوعات", "body": "- فتح دائرة التبريد بغير فني مؤهل على النظام\n- تعديل إعدادات النظام دون توثيق\n- فصل الوحدة الخارجية فجأة أثناء تشغيل الداخلية دون إجراء الصانع"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "G-06 · M-01", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',12,'wrench','التكييف','MNT','["قراءة الأكواد", "عزل الكهرباء", "فلاتر وملفات الوحدات الداخلية", "مضخات التصريف", "الوحدة الخارجية", "عزل الأنابيب", "الضغوط والحرارة", "جدولة التحكم"]'::jsonb,'{"ppe": ["gloves", "goggles"], "steps": [{"i": "screen", "t": {"ar": "اقرأ أكواد الأعطال من التحكم", "en": "Read fault codes from controller", "ur": "کنٹرولر سے خرابی کے کوڈ پڑھیں", "bn": "কন্ট্রোলার থেকে ত্রুটি কোড পড়ুন", "hi": "कंट्रोलर से खराबी कोड पढ़ें", "tl": "Basahin ang fault code sa controller"}}, {"i": "power", "t": {"ar": "افصل الكهرباء واقفلها وتأكد من انعدامها", "en": "Isolate, lock out and test for zero power", "ur": "بجلی بند، لاک کریں اور چیک کریں", "bn": "বিদ্যুৎ বন্ধ, লক করে পরীক্ষা করুন", "hi": "बिजली बंद, लॉक करें और जांचें", "tl": "Patayin, i-lock at subukan ang kuryente"}}, {"i": "filter", "t": {"ar": "فلاتر وملفات الوحدات الداخلية", "en": "Indoor unit filters and coils", "ur": "اندرونی یونٹ کے فلٹر اور کوائل", "bn": "ভেতরের ইউনিটের ফিল্টার ও কয়েল", "hi": "अंदरूनी यूनिट के फ़िल्टर और कॉइल", "tl": "Filter at coil ng indoor unit"}}, {"i": "drop", "t": {"ar": "افحص مضخة التصريف", "en": "Check the drain pump", "ur": "ڈرین پمپ چیک کریں", "bn": "ড্রেন পাম্প পরীক্ষা করুন", "hi": "ड्रेन पंप जांचें", "tl": "Suriin ang drain pump"}}, {"i": "outdoor", "t": {"ar": "نظّف الوحدة الخارجية", "en": "Clean the outdoor unit", "ur": "باہر والا یونٹ صاف کریں", "bn": "বাইরের ইউনিট পরিষ্কার করুন", "hi": "बाहरी यूनिट साफ करें", "tl": "Linisin ang outdoor unit"}}, {"i": "thermo", "t": {"ar": "راقب الضغوط والحرارة", "en": "Monitor pressures and temperature", "ur": "پریشر اور درجہ حرارت دیکھیں", "bn": "চাপ ও তাপমাত্রা দেখুন", "hi": "दबाव और तापमान देखें", "tl": "Bantayan ang presyon at temperatura"}}], "donts": [{"i": "nogas", "t": {"ar": "لا تفتح دائرة التبريد إلا فني مؤهل", "en": "Only qualified tech opens refrigerant circuit", "ur": "صرف مستند ٹیکنیشن گیس سرکٹ کھولے", "bn": "শুধু দক্ষ টেকনিশিয়ান গ্যাস সার্কিট খুলবে", "hi": "सिर्फ योग्य तकनीशियन गैस सर्किट खोले", "tl": "Kwalipikadong tech lang ang magbubukas ng circuit"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M04','الصيانة الدورية لوحدات مناولة الهواء (AHU) ووحدات الملفات (FCU)','فنيو التكييف ومقاول التشغيل والصيانة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "وحدات مناولة الهواء التي تخدم الأقسام (وأهمها ما يخدم المناطق ذات الضغط الخاص: العزل، العمليات، التعقيم)، ووحدات الملفات المروحية في الغرف، في الأنظمة التي تعمل بماء مبرد."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عزل الكهرباء عن الوحدة بالقفل والبطاقة والتحقق من انعدام الجهد قبل فتحها (M-01)\n- العمل على ارتفاع بسلم أو منصة معتمدة\n- التعامل مع وسيط التبريد بفني مؤهل وقفازات ونظارة، ولا يُطلق للجو\n- نظارة وكمامة عند تنظيف الملفات بالمواد أو الهواء المضغوط\n- تنسيق أي إيقاف لوحدة تخدم منطقة حرجة كإيقاف مخطط بإشعار وبديل (M-02)"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- مقياس فرق الضغط والهواء\n- فلاتر بديلة بالدرجات المحددة\n- سيور ومواد تشحيم\n- منظف ملفات ومعالج لحوض التكثيف"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مراجعة الإنذارات والقراءات من نظام إدارة المبنى إن وُجد | — |\n| 2 | تنسيق الإيقاف وعزل الكهرباء | الإشعار صدر للمنطقة الحرجة |\n| 3 | الفلاتر الأولية والثانوية: قراءة فرق الضغط والاستبدال عند الحد أو الموعد | فلاتر محكمة بلا تسريب جانبي |\n| 4 | ملف التبريد وحوض التكثيف والمصيدة: تنظيف ومعالجة وفحص التصريف | لا ماء راكد |\n| 5 | المروحة: الشفرات، السير، المحامل، المحرك، الاهتزاز | — |\n| 6 | المخمدات ومشغلاتها وصمامات الماء المبرد ومشغلاتها | تتحرك بالكامل |\n| 7 | الغلاف والأبواب وعزلها | محكمة |\n| 8 | FCU: الفلتر، الملف، الحوض، التصريف، الثرموستات | — |\n| 9 | التشغيل والتحقق من الحرارة والرطوبة والضغط في المناطق الخاصة | الضغط الموجب أو السالب مطابق بقراءة |\n| 10 | تسجيل القراءات وإغلاق الأمر | — |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الفلاتر الأولية | شهرياً أو عند حد فرق الضغط |\n| الفلاتر الثانوية وعالية الكفاءة | بحسب فرق الضغط وتوصية الصانع |\n| الملفات والأحواض والسيور | كل 3 أشهر |\n| فحص ضغط المناطق الخاصة | شهرياً |\n| FCU | كل 3 أشهر |"}, {"key": "accept", "title": "معايير القبول", "body": "- الفلاتر ضمن حد فرق الضغط\n- لا ماء راكد في الأحواض\n- الضغوط في المناطق الخاصة مطابقة"}, {"key": "donts", "title": "ممنوعات", "body": "- إيقاف وحدة منطقة حرجة دون إشعار وبديل\n- ترك أبواب الوحدة مفتوحة أثناء التشغيل\n- تجاوز فرق الضغط المسموح للفلاتر"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "G-06 · M-01 · M-02 · PL-06", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',13,'wrench','التكييف','MNT','["الإنذارات والقراءات", "تنسيق الإيقاف وعزل الكهرباء", "الفلاتر وفرق الضغط", "الملف وحوض التكثيف", "المروحة والسير والمحامل", "المخمدات والصمامات", "الغلاف والأبواب", "وحدات FCU", "ضغط المناطق الخاصة", "تسجيل القراءات"]'::jsonb,'{"ppe": ["gloves", "goggles", "mask"], "steps": [{"i": "phone", "t": {"ar": "نسّق الإيقاف للمناطق الحرجة", "en": "Coordinate shutdown for critical areas", "ur": "اہم جگہوں کے لیے بندش کی اطلاع دیں", "bn": "গুরুত্বপূর্ণ এলাকায় বন্ধের সমন্বয় করুন", "hi": "महत्वपूर्ण क्षेत्रों के लिए बंदी का समन्वय करें", "tl": "I-coordinate ang shutdown sa kritikal na lugar"}}, {"i": "power", "t": {"ar": "افصل الكهرباء واقفلها وتأكد من انعدامها", "en": "Isolate, lock out and test for zero power", "ur": "بجلی بند، لاک کریں اور چیک کریں", "bn": "বিদ্যুৎ বন্ধ, লক করে পরীক্ষা করুন", "hi": "बिजली बंद, लॉक करें और जांचें", "tl": "Patayin, i-lock at subukan ang kuryente"}}, {"i": "gauge", "t": {"ar": "اقرأ فرق ضغط الفلاتر واستبدلها عند الحد", "en": "Read filter pressure drop, replace at limit", "ur": "فلٹر کا پریشر دیکھیں، حد پر بدلیں", "bn": "ফিল্টারের চাপ দেখে সীমায় বদলান", "hi": "फ़िल्टर दबाव देखें, सीमा पर बदलें", "tl": "Basahin ang pressure ng filter, palitan sa limit"}}, {"i": "coil", "t": {"ar": "الملف وحوض التكثيف والمصيدة", "en": "Coil, drain pan and trap", "ur": "کوائل، ڈرین پین اور ٹریپ", "bn": "কয়েল, ড্রেন প্যান ও ট্র্যাপ", "hi": "कॉइल, ड्रेन पैन और ट्रैप", "tl": "Coil, drain pan at trap"}}, {"i": "belt", "t": {"ar": "المروحة والسير والمحامل", "en": "Fan, belt and bearings", "ur": "پنکھا، بیلٹ اور بیئرنگ", "bn": "ফ্যান, বেল্ট ও বিয়ারিং", "hi": "पंखा, बेल्ट और बेयरिंग", "tl": "Bentilador, belt at bearing"}}, {"i": "valve", "t": {"ar": "المخمدات والصمامات تتحرك بالكامل", "en": "Dampers and valves move fully", "ur": "ڈیمپر اور والو پورے حرکت کریں", "bn": "ড্যাম্পার ও ভালভ পুরো নড়ে কিনা", "hi": "डैम्पर और वाल्व पूरे चलें", "tl": "Gumagalaw nang buo ang damper at valve"}}, {"i": "gauge", "t": {"ar": "تحقق من ضغط المناطق الخاصة", "en": "Verify special room pressure", "ur": "خاص کمروں کا پریشر چیک کریں", "bn": "বিশেষ কক্ষের চাপ যাচাই করুন", "hi": "विशेष कमरों का दबाव जांचें", "tl": "Tiyakin ang presyon ng espesyal na kuwarto"}}], "donts": [{"i": "noentry", "t": {"ar": "لا إيقاف لمنطقة حرجة بلا إشعار", "en": "No critical area shutdown without notice", "ur": "اطلاع کے بغیر اہم جگہ بند نہ کریں", "bn": "নোটিশ ছাড়া গুরুত্বপূর্ণ এলাকা বন্ধ নয়", "hi": "सूचना के बिना महत्वपूर्ण क्षेत्र बंद नहीं", "tl": "Walang shutdown nang walang abiso"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M05','التشغيل والصيانة الدورية للمبردات (التشيلر)','فنيو المبردات المؤهلون ومقاول التشغيل والصيانة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "المبردات المبردة بالهواء أو بالماء ومضخاتها، وهي أهم أصول التكييف في المستشفيات. توقفها في الصيف يوقف التكييف عن مبنى كامل، لذا تُراقب يومياً وتُصان بحسب الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عزل الكهرباء عن الوحدة بالقفل والبطاقة والتحقق من انعدام الجهد قبل فتحها (M-01)\n- العمل على ارتفاع بسلم أو منصة معتمدة\n- التعامل مع وسيط التبريد بفني مؤهل وقفازات ونظارة، ولا يُطلق للجو\n- نظارة وكمامة عند تنظيف الملفات بالمواد أو الهواء المضغوط\n- المبرد لا يُفتح إلا بفني مؤهل أو الوكيل\n- الإيقاف المخطط لمبرد مع ضمان تشغيل البديل (M-02)"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- سجل التشغيل اليومي\n- جهاز التشخيص بحسب الصانع\n- معدات تحليل الزيت ووسيط التبريد عند الحاجة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | الجولة اليومية: حرارة الماء الداخل والخارج، الضغوط، تيار الضواغط، الإنذارات | السجل اليومي مكتمل |\n| 2 | مضخات الماء المبرد: الضغط، الأصوات، التسرب، الاهتزاز | — |\n| 3 | المكثفات (للمبرد بالهواء): تنظيف الملفات من الغبار | الزعانف نظيفة |\n| 4 | مراجعة جودة معالجة المياه (للدوائر المغلقة) بحسب البرنامج | — |\n| 5 | التبديل بين المبردات والمضخات لتوزيع ساعات التشغيل | بحسب الجدول |\n| 6 | الصيانة الدورية الكهربائية والميكانيكية بحسب الصانع، وتحليل الزيت | — |\n| 7 | اختبار التحويل للمبرد الاحتياطي | يقلع ويحمل |\n| 8 | تسجيل القراءات والأعمال | — |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الجولة والقراءات | يومياً |\n| تنظيف المكثفات | شهرياً في الصيف، وكل 3 أشهر شتاء |\n| الصيانة الوقائية الشاملة | كل 6 أشهر أو بحسب الصانع |\n| تحليل الزيت | سنوياً |\n| جاهزية الصيف | أبريل (K-08) |"}, {"key": "accept", "title": "معايير القبول", "body": "- حرارة الماء الخارج ضمن نقطة الضبط\n- لا إنذارات قائمة\n- السجل اليومي مكتمل"}, {"key": "donts", "title": "ممنوعات", "body": "- تجاوز أجهزة الحماية أو إسكات الإنذارات\n- تشغيل مبرد واحد دائماً وترك الآخر خاملاً\n- فتح الدائرة بغير مؤهل"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "G-06 · M-02 · M-03 · K-08", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',14,'wrench','التكييف','MNT','["قراءات الماء الداخل والخارج", "الضغوط وتيار الضواغط", "الإنذارات", "المضخات", "تنظيف المكثفات", "معالجة المياه", "التبديل بين المبردات", "اختبار الاحتياطي"]'::jsonb,'{"ppe": ["gloves", "goggles", "ear"], "steps": [{"i": "clipboard", "t": {"ar": "سجّل القراءات اليومية", "en": "Record daily readings", "ur": "روزانہ کی ریڈنگ لکھیں", "bn": "প্রতিদিনের রিডিং লিখুন", "hi": "रोज़ाना की रीडिंग लिखें", "tl": "Itala ang araw-araw na reading"}}, {"i": "thermo", "t": {"ar": "حرارة الماء الداخل والخارج", "en": "Water in and out temperature", "ur": "آنے اور جانے والے پانی کا درجہ حرارت", "bn": "ঢোকা ও বের হওয়া পানির তাপমাত্রা", "hi": "आने और जाने वाले पानी का तापमान", "tl": "Temperatura ng tubig papasok at palabas"}}, {"i": "gauge", "t": {"ar": "الضغوط وتيار الضواغط", "en": "Pressures and compressor current", "ur": "پریشر اور کمپریسر کرنٹ", "bn": "চাপ ও কম্প্রেসরের কারেন্ট", "hi": "दबाव और कंप्रेसर करंट", "tl": "Presyon at kuryente ng compressor"}}, {"i": "alarm", "t": {"ar": "الإنذارات: لا تسكتها، أبلغ", "en": "Alarms: do not silence, report", "ur": "الارم بند نہ کریں، اطلاع دیں", "bn": "অ্যালার্ম বন্ধ নয়, জানান", "hi": "अलार्म बंद न करें, बताएं", "tl": "Alarm: huwag patayin, i-report"}}, {"i": "outdoor", "t": {"ar": "نظّف المكثفات", "en": "Clean condensers", "ur": "کنڈینسر صاف کریں", "bn": "কনডেন্সার পরিষ্কার করুন", "hi": "कंडेंसर साफ करें", "tl": "Linisin ang condenser"}}, {"i": "swap", "t": {"ar": "بدّل بين المبردات حسب الجدول", "en": "Rotate chillers per schedule", "ur": "شیڈول کے مطابق چلر بدلیں", "bn": "সূচি অনুযায়ী চিলার বদলান", "hi": "शेड्यूल अनुसार चिलर बदलें", "tl": "Salitan ang chiller ayon sa iskedyul"}}], "donts": [{"i": "noalarm", "t": {"ar": "لا تتجاوز أجهزة الحماية", "en": "Never bypass protection devices", "ur": "حفاظتی آلات کو بائی پاس نہ کریں", "bn": "সুরক্ষা যন্ত্র বাইপাস করবেন না", "hi": "सुरक्षा उपकरण बायपास न करें", "tl": "Huwag i-bypass ang proteksyon"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M06','الاختبار الشهري للمولد الاحتياطي تحت الحمل','فنيو الكهرباء والمولدات','[{"key": "purpose", "title": "الغرض والنطاق", "body": "اختبار يثبت أن المولد سيقلع ويحمل المنشأة عند انقطاع الكهرباء. المرجع NFPA 110 وتوصيات الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- إشعار المنشأة قبل الاختبار، خاصة المناطق الحرجة (M-02)\n- حماية السمع قرب المولد\n- لا تدخين ولا لهب قرب الوقود"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- سجل المولد\n- أمبير كلّابي أو قراءة لوحة المولد"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | الفحص قبل التشغيل: الوقود، الزيت، ماء التبريد، البطاريات وشاحنها، التسربات، السيور | كل البنود سليمة |\n| 2 | إشعار المنشأة والمناطق الحرجة بوقت الاختبار | الإشعار صدر |\n| 3 | بدء الاختبار من مفتاح التحويل الآلي (محاكاة انقطاع) لا من المولد فقط | التحويل تم آلياً |\n| 4 | تسجيل زمن الإقلاع ونقل الحمل | ضمن ثوانٍ بحسب تصنيف النظام |\n| 5 | التشغيل 30 دقيقة على الأقل تحت حمل لا يقل عن 30٪ من القدرة الاسمية أو بحسب الصانع | الحمل مسجل |\n| 6 | قراءات أثناء التشغيل: الجهد، التردد، التيار، ضغط الزيت، الحرارة | ضمن المعتاد |\n| 7 | إعادة التحويل للتغذية العامة ومراقبة فترة تبريد المولد | التحويل العكسي تم |\n| 8 | إعادة المفتاح إلى «آلي» والتأكد | الوضع آلي |\n| 9 | تسجيل كل القراءات وإغلاق الأمر | — |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الفحص البصري | أسبوعياً |\n| الاختبار تحت الحمل | شهرياً (K-01) |\n| الاختبار الممتد | كل 36 شهراً بحسب NFPA 110 |\n| الصيانة الشاملة | سنوياً أو بحسب ساعات التشغيل |"}, {"key": "accept", "title": "معايير القبول", "body": "- الإقلاع ونقل الحمل ضمن الزمن\n- الحمل المطلوب لمدة 30 دقيقة\n- المفتاح على «آلي» بعد الاختبار"}, {"key": "donts", "title": "ممنوعات", "body": "- الاختبار بلا حمل فقط بشكل متكرر\n- ترك المفتاح على يدوي أو إيقاف\n- تجاوز إنذارات الحماية"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "M-03 · G-06 · K-01 · PL-06", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',15,'power','الأنظمة الكهربائية','MNT','["الفحص قبل التشغيل", "إشعار المنشأة", "محاكاة الانقطاع من مفتاح التحويل", "زمن الإقلاع ونقل الحمل", "30 دقيقة تحت الحمل", "القراءات أثناء التشغيل", "التحويل العكسي", "المفتاح على آلي"]'::jsonb,'{"ppe": ["ear", "gloves"], "steps": [{"i": "fuel", "t": {"ar": "افحص الوقود والزيت والماء والبطارية", "en": "Check fuel, oil, coolant, battery", "ur": "ایندھن، تیل، پانی اور بیٹری چیک کریں", "bn": "জ্বালানি, তেল, পানি ও ব্যাটারি দেখুন", "hi": "ईंधन, तेल, पानी और बैटरी जांचें", "tl": "Suriin ang gasolina, langis, tubig, baterya"}}, {"i": "phone", "t": {"ar": "أبلغ المنشأة بوقت الاختبار", "en": "Notify the facility of test time", "ur": "سہولت کو ٹیسٹ کا وقت بتائیں", "bn": "ফ্যাসিলিটিকে টেস্টের সময় জানান", "hi": "सुविधा को टेस्ट का समय बताएं", "tl": "Abisuhan ang pasilidad sa oras ng test"}}, {"i": "switch", "t": {"ar": "ابدأ من مفتاح التحويل الآلي", "en": "Start from the transfer switch", "ur": "ٹرانسفر سوئچ سے شروع کریں", "bn": "ট্রান্সফার সুইচ থেকে শুরু করুন", "hi": "ट्रांसफर स्विच से शुरू करें", "tl": "Simulan sa transfer switch"}}, {"i": "clock", "t": {"ar": "سجّل زمن الإقلاع ونقل الحمل", "en": "Record start and transfer time", "ur": "اسٹارٹ اور ٹرانسفر کا وقت لکھیں", "bn": "চালু ও ট্রান্সফারের সময় লিখুন", "hi": "स्टार्ट और ट्रांसफर का समय लिखें", "tl": "Itala ang oras ng pag-andar at paglipat"}}, {"i": "generator", "t": {"ar": "شغّل 30 دقيقة تحت الحمل", "en": "Run 30 minutes under load", "ur": "30 منٹ لوڈ پر چلائیں", "bn": "৩০ মিনিট লোডে চালান", "hi": "30 मिनट लोड पर चलाएं", "tl": "Paandarin ng 30 minuto na may karga"}}, {"i": "gauge", "t": {"ar": "سجّل الجهد والتردد والضغط والحرارة", "en": "Record voltage, frequency, oil, temp", "ur": "وولٹیج، فریکوئنسی، تیل، درجہ حرارت لکھیں", "bn": "ভোল্টেজ, ফ্রিকোয়েন্সি, তেল, তাপ লিখুন", "hi": "वोल्टेज, फ्रीक्वेंसी, तेल, तापमान लिखें", "tl": "Itala ang boltahe, frequency, langis, init"}}, {"i": "auto", "t": {"ar": "أعد المفتاح إلى «آلي»", "en": "Return switch to AUTO", "ur": "سوئچ واپس \"آٹو\" پر کریں", "bn": "সুইচ আবার \"অটো\" করুন", "hi": "स्विच वापस \"ऑटो\" पर करें", "tl": "Ibalik ang switch sa AUTO"}}], "donts": [{"i": "nomanual", "t": {"ar": "لا تترك المفتاح على يدوي أو إيقاف", "en": "Never leave switch on MANUAL or OFF", "ur": "سوئچ مینوئل یا آف پر نہ چھوڑیں", "bn": "সুইচ ম্যানুয়াল বা অফে রাখবেন না", "hi": "स्विच मैनुअल या ऑफ पर न छोड़ें", "tl": "Huwag iwan ang switch sa MANUAL o OFF"}}, {"i": "nofire", "t": {"ar": "لا تدخين ولا لهب قرب الوقود", "en": "No smoking or flame near fuel", "ur": "ایندھن کے قریب سگریٹ یا آگ منع", "bn": "জ্বালানির কাছে ধূমপান বা আগুন নিষেধ", "hi": "ईंधन के पास धूम्रपान या आग मना", "tl": "Bawal manigarilyo o apoy malapit sa gasolina"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-M07','تنظيف خزانات المياه وتعقيمها','فنيو الصيانة ومقاول تنظيف الخزانات المرخص','[{"key": "purpose", "title": "الغرض والنطاق", "body": "تنظيف وتعقيم خزانات المياه العلوية والأرضية للوقاية من التلوث والليجيونيلا، ضمن خطة إدارة المياه (K-10)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- العمل في الخزان مكان محصور: تصريح عمل، قياس هواء، مراقب خارجي (M-01)\n- ملابس ومعدات نظيفة مخصصة لا تُستخدم في غيره\n- التعامل مع الكلور المركز بالقفازات والنظارة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- مضخة تفريغ\n- فرش ومكانس مخصصة\n- مادة التعقيم المعتمدة\n- أدوات قياس الكلور المتبقي\n- عبوات أخذ العينات"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | إشعار المنشأة وتأمين مصدر بديل إن لزم (M-02) | البديل جاهز |\n| 2 | عزل الخزان وتفريغه | — |\n| 3 | إزالة الرواسب وتنظيف الجدران والأرضية والسقف ميكانيكياً | بلا رواسب أو طحالب |\n| 4 | فحص الجدران والعزل والغطاء والفتحات والشبك | الغطاء محكم والفتحات مشبكة |\n| 5 | التعقيم بالتركيز والمدة بحسب الطريقة المعتمدة (AWWA C652 أو اشتراطات الجهة المختصة) | المدة محترمة |\n| 6 | الشطف والتعبئة وقياس الكلور المتبقي | ضمن الحدود المعتمدة |\n| 7 | أخذ عينة للفحص المخبري بحسب الخطة | العينة أُرسلت |\n| 8 | إعادة الخزان للخدمة وتسجيل العمل | شهادة المقاول محفوظة |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| تنظيف الخزانات وتعقيمها | كل 6 أشهر على الأقل، أو بحسب اشتراطات الجهة المختصة |\n| قياس الكلور المتبقي | بحسب خطة إدارة المياه |\n| فحص الأغطية والفتحات | شهرياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- خزان نظيف بلا رواسب\n- نتيجة الفحص مطابقة\n- شهادة التنظيف محفوظة"}, {"key": "donts", "title": "ممنوعات", "body": "- دخول الخزان بلا تصريح ومراقب\n- استخدام أدوات الخزان في غيره\n- إعادة الخزان قبل انتهاء مدة التعقيم والشطف"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "G-06 · M-01 · K-10 · PL-06", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',16,'wrench','الأنظمة الصحية','MNT','["إشعار المنشأة والبديل", "تصريح المكان المحصور", "التفريغ والتنظيف الميكانيكي", "فحص الغطاء والفتحات", "التعقيم بالطريقة المعتمدة", "الشطف وقياس الكلور", "العينة المخبرية", "الشهادة"]'::jsonb,'{"ppe": ["gloves", "goggles", "boots", "harness"], "steps": [{"i": "permit", "t": {"ar": "تصريح مكان محصور ومراقب خارجي", "en": "Confined space permit and standby person", "ur": "بند جگہ کا پرمٹ اور باہر نگران", "bn": "বদ্ধ স্থানের অনুমতি ও বাইরে পাহারাদার", "hi": "बंद जगह का परमिट और बाहर निगरानी", "tl": "Permit sa confined space at bantay sa labas"}}, {"i": "phone", "t": {"ar": "أبلغ المنشأة وجهّز البديل", "en": "Notify facility, prepare backup water", "ur": "سہولت کو بتائیں، متبادل تیار کریں", "bn": "ফ্যাসিলিটিকে জানান, বিকল্প প্রস্তুত করুন", "hi": "सुविधा को बताएं, विकल्प तैयार करें", "tl": "Abisuhan ang pasilidad, ihanda ang reserba"}}, {"i": "tank", "t": {"ar": "فرّغ الخزان ونظّفه", "en": "Empty and clean the tank", "ur": "ٹینک خالی اور صاف کریں", "bn": "ট্যাংক খালি করে পরিষ্কার করুন", "hi": "टंकी खाली और साफ करें", "tl": "Alisan ng laman at linisin ang tangke"}}, {"i": "lock", "t": {"ar": "افحص الغطاء والفتحات", "en": "Check lid and vents", "ur": "ڈھکن اور سوراخ چیک کریں", "bn": "ঢাকনা ও ছিদ্র পরীক্ষা করুন", "hi": "ढक्कन और छेद जांचें", "tl": "Suriin ang takip at butas"}}, {"i": "spray", "t": {"ar": "عقّم بالطريقة المعتمدة", "en": "Disinfect by approved method", "ur": "منظور طریقے سے جراثیم کشی کریں", "bn": "অনুমোদিত পদ্ধতিতে জীবাণুমুক্ত করুন", "hi": "मंज़ूर तरीके से कीटाणुरहित करें", "tl": "I-disinfect sa aprubadong paraan"}}, {"i": "drop", "t": {"ar": "اشطف وقس الكلور", "en": "Rinse and test chlorine", "ur": "دھوئیں اور کلورین چیک کریں", "bn": "ধুয়ে ক্লোরিন পরীক্ষা করুন", "hi": "धोएं और क्लोरीन जांचें", "tl": "Banlawan at subukan ang chlorine"}}, {"i": "sample", "t": {"ar": "خذ عينة للمختبر", "en": "Take a lab sample", "ur": "لیب کے لیے نمونہ لیں", "bn": "ল্যাবের জন্য নমুনা নিন", "hi": "लैब के लिए नमूना लें", "tl": "Kumuha ng sample para sa lab"}}], "donts": [{"i": "noentry", "t": {"ar": "لا دخول بدون تصريح ومراقب", "en": "No entry without permit and standby", "ur": "پرمٹ اور نگران کے بغیر داخلہ منع", "bn": "অনুমতি ও পাহারাদার ছাড়া প্রবেশ নিষেধ", "hi": "परमिट और निगरानी के बिना प्रवेश मना", "tl": "Bawal pumasok nang walang permit at bantay"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-S01','الفحص الشهري لطفايات الحريق','مشرفو الأمن والسلامة وفنيو الإطفاء','[{"key": "purpose", "title": "الغرض والنطاق", "body": "فحص بصري شهري يضمن أن كل طفاية في مكانها وجاهزة. المرجع NFPA 10، والصيانة السنوية والاختبار الهيدروستاتيكي بمقاول معتمد."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- لا تفريغ للطفاية أثناء الفحص"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- قائمة مواقع الطفايات\n- بطاقات الفحص"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | الطفاية في موقعها المحدد، ظاهرة، ولا يعوق الوصول إليها شيء | اللوحة الإرشادية فوقها |\n| 2 | النوع مناسب للخطر في الموقع (مثلاً ثاني أكسيد الكربون قرب الكهرباء) | — |\n| 3 | مؤشر الضغط في المنطقة الخضراء | — |\n| 4 | مسمار الأمان والختم سليمان | — |\n| 5 | لا تلف أو صدأ أو انسداد في الخرطوم والفوهة | — |\n| 6 | بطاقة الفحص موقعة ومؤرخة | — |\n| 7 | تسجيل الطفايات غير الصالحة وبلاغ استبدال فوري، ووضع بديلة | لا موقع بلا طفاية |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الفحص البصري | شهرياً |\n| الصيانة السنوية | سنوياً بمقاول معتمد |\n| الاختبار الهيدروستاتيكي | بحسب نوع الطفاية في NFPA 10 |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل المواقع فيها طفاية صالحة\n- البطاقات موقعة"}, {"key": "donts", "title": "ممنوعات", "body": "- تحريك الطفاية من موقعها\n- وضع أشياء أمامها\n- ترك موقع بلا طفاية"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "H-06 · PL-04", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',17,'flame','السلامة من الحريق','SAF','["الموقع والظهور والوصول", "النوع المناسب", "مؤشر الضغط", "المسمار والختم", "الخرطوم والفوهة", "توقيع البطاقة", "بلاغ الطفايات غير الصالحة"]'::jsonb,'{"ppe": [], "steps": [{"i": "extinguisher", "t": {"ar": "الطفاية في مكانها وظاهرة", "en": "Extinguisher in place and visible", "ur": "آگ بجھانے والا آلہ اپنی جگہ اور نظر آئے", "bn": "অগ্নিনির্বাপক যথাস্থানে ও দৃশ্যমান", "hi": "अग्निशामक अपनी जगह और दिखाई दे", "tl": "Nasa lugar at kita ang extinguisher"}}, {"i": "gauge", "t": {"ar": "المؤشر في الأخضر", "en": "Gauge in the green", "ur": "گیج سبز میں ہو", "bn": "গেজ সবুজে", "hi": "गेज हरे में हो", "tl": "Nasa berde ang gauge"}}, {"i": "pin", "t": {"ar": "المسمار والختم سليمان", "en": "Pin and seal intact", "ur": "پن اور سیل ٹھیک ہوں", "bn": "পিন ও সিল ঠিক আছে", "hi": "पिन और सील ठीक हों", "tl": "Buo ang pin at selyo"}}, {"i": "hose", "t": {"ar": "الخرطوم والفوهة بلا تلف", "en": "Hose and nozzle undamaged", "ur": "پائپ اور نوزل ٹھیک ہوں", "bn": "পাইপ ও নজল ঠিক আছে", "hi": "पाइप और नोज़ल ठीक हों", "tl": "Walang sira ang hose at nozzle"}}, {"i": "tag", "t": {"ar": "وقّع بطاقة الفحص", "en": "Sign the inspection tag", "ur": "معائنہ ٹیگ پر دستخط کریں", "bn": "পরিদর্শন ট্যাগে সই করুন", "hi": "निरीक्षण टैग पर हस्ताक्षर करें", "tl": "Pumirma sa inspection tag"}}], "donts": [{"i": "noblock", "t": {"ar": "لا تضع شيئاً أمام الطفاية", "en": "Never block the extinguisher", "ur": "آلے کے سامنے کچھ نہ رکھیں", "bn": "নির্বাপকের সামনে কিছু রাখবেন না", "hi": "अग्निशामक के सामने कुछ न रखें", "tl": "Huwag harangan ang extinguisher"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ('WI-S02','الفحص الدوري لإنارة الطوارئ ولوحات المخارج','فنيو الكهرباء والأمن والسلامة','[{"key": "purpose", "title": "الغرض والنطاق", "body": "إنارة الطوارئ ولوحات المخارج تقود الناس للخارج عند انقطاع الكهرباء أو الحريق. المرجع NFPA 101."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- العمل على ارتفاع بسلم معتمد\n- تنسيق الاختبار مع المنشأة حتى لا يُفاجأ المرضى"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- قائمة المواقع\n- بطاريات ولمبات بديلة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | كل لوحة مخرج مضيئة ومقروءة واتجاه السهم صحيح | — |\n| 2 | اختبار شهري بزر الاختبار: الإضاءة تعمل على البطارية | تعمل |\n| 3 | اختبار سنوي لمدة التشغيل الكاملة على البطارية بحسب المتطلب | المدة متحققة |\n| 4 | استبدال البطاريات واللمبات الضعيفة | — |\n| 5 | تسجيل النتائج وبلاغ المعيب | — |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الاختبار القصير | شهرياً |\n| اختبار المدة الكاملة | سنوياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل اللوحات مضيئة\n- كل وحدات الطوارئ تعمل على البطارية"}, {"key": "donts", "title": "ممنوعات", "body": "- إزالة لوحة مخرج أو تغطيتها\n- ترك وحدة معيبة دون بلاغ"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "auto": "checklist", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة."}, {"key": "refs", "title": "المراجع والإجراءات", "auto": "procs", "procs": "H-06 · PL-04", "body": "الإجراءات والقواعد والخطط الحاكمة لهذا العمل."}]'::jsonb,'wi',18,'flame','السلامة من الحريق','SAF','["اللوحات مضيئة والأسهم صحيحة", "الاختبار الشهري", "اختبار المدة السنوي", "استبدال المعيب", "تسجيل النتائج"]'::jsonb,'{"ppe": ["ladder"], "steps": [{"i": "exit", "t": {"ar": "لوحة المخرج مضيئة والسهم صحيح", "en": "Exit sign lit, arrow correct", "ur": "ایگزٹ بورڈ روشن، تیر درست", "bn": "এক্সিট সাইন জ্বলছে, তীর সঠিক", "hi": "एग्ज़िट बोर्ड जलता हो, तीर सही", "tl": "Nakasindi ang EXIT, tama ang arrow"}}, {"i": "bulb", "t": {"ar": "اضغط زر الاختبار: الإضاءة تعمل", "en": "Press test button: light works", "ur": "ٹیسٹ بٹن دبائیں: روشنی چلے", "bn": "টেস্ট বোতাম চাপুন: আলো জ্বলবে", "hi": "टेस्ट बटन दबाएं: रोशनी चले", "tl": "Pindutin ang test: gumagana ang ilaw"}}, {"i": "battery", "t": {"ar": "استبدل البطاريات الضعيفة", "en": "Replace weak batteries", "ur": "کمزور بیٹریاں بدلیں", "bn": "দুর্বল ব্যাটারি বদলান", "hi": "कमज़ोर बैटरी बदलें", "tl": "Palitan ang mahinang baterya"}}, {"i": "clipboard", "t": {"ar": "سجّل النتائج وأبلغ عن المعيب", "en": "Record results, report faults", "ur": "نتائج لکھیں، خرابی بتائیں", "bn": "ফলাফল লিখুন, ত্রুটি জানান", "hi": "नतीजे लिखें, खराबी बताएं", "tl": "Itala ang resulta, i-report ang sira"}}], "donts": [{"i": "nocover", "t": {"ar": "لا تغطِّ لوحات المخارج", "en": "Never cover exit signs", "ur": "ایگزٹ بورڈ کبھی نہ ڈھانپیں", "bn": "এক্সিট সাইন ঢাকবেন না", "hi": "एग्ज़िट बोर्ड कभी न ढकें", "tl": "Huwag takpan ang EXIT sign"}}]}'::jsonb) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values
 ('R-45','العمل الدوري على تعليمات معتمدة','التشغيل','كل عمل دوري متكرر (صيانة وقائية، تنظيف، فحص) يُنفذ على تعليمات عمل معتمدة، وقائمة تحقق أمر العمل مأخوذة منها، فيُنفذ العمل نفسه بالطريقة نفسها مهما تغير الفني أو المقاول.','["كل خطة صيانة دورية مربوطة بتعليمات عملها، وبنودها قائمة تحقق إلزامية قبل الإغلاق", "عقود النظافة والتشغيل والصيانة تُلزم المقاول بتعليمات العمل المعتمدة", "تُراجع التعليمات سنوياً وعند تغير المعدات أو توصيات الصانع", "تعليمات الصانع تُقدم عند تعارضها مع التعليمات، وتُحدَّث التعليمات بها"]'::jsonb,'MNT','G-06','',45)
 on conflict (code) do nothing;
